def _font(size, bold=True, names="arial"):
    """SysFont on desktop; bundled default font in the browser (no system fonts there)."""
    if not WEB:
        try:
            return pygame.font.SysFont(names, size, bold=bold)
        except Exception:
            pass
    f = pygame.font.Font(None, int(size * 1.25))
    try:
        f.set_bold(bold)
    except Exception:
        pass
    return f

