_ROM_CACHE = {}


def rom_heart_surf(size, col):
    key = ("h", int(size), col)
    s = _ROM_CACHE.get(key)
    if s is None:
        n = max(5, int(size))
        s = pygame.Surface((n * 2 + 4, n * 2 + 4), pygame.SRCALPHA)
        pts = []
        for i in range(64):
            t = i / 64.0 * math.tau
            hx = 16 * math.sin(t) ** 3
            hy = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t))
            pts.append((n + 2 + hx / 16.0 * n, n + 2 + (hy - 4.5) / 17.0 * n))
        pygame.draw.polygon(s, col, pts)
        pygame.draw.circle(s, (255, 255, 255, 150), (int(n * 0.62), int(n * 0.68)), max(1, int(n * 0.16)))
        _ROM_CACHE[key] = s
    return s


def rom_draw_heart(x, y, size, col=(255, 70, 120), alpha=255):
    s = rom_heart_surf(size, col)
    s.set_alpha(max(0, min(255, int(alpha))))
    screen.blit(s, s.get_rect(center=(int(x), int(y))))


def rom_lips_surf(w):
    w = max(8, int(w))
    key = ("l", w)
    s = _ROM_CACHE.get(key)
    if s is None:
        h = int(w * 0.9) + 4
        s = pygame.Surface((w * 2 + 6, h * 2 + 6), pygame.SRCALPHA)
        cx, cy = w + 3, h + 3

        def P(pts):
            return [(cx + px * w, cy + py * w) for px, py in pts]
        upper = [(-1, 0), (-.72, -.42), (-.38, -.62), (0, -.34), (.38, -.62), (.72, -.42), (1, 0), (0, .09)]
        lower = [(-1, 0), (0, .09), (1, 0), (.78, .48), (.38, .78), (0, .86), (-.38, .78), (-.78, .48)]
        pygame.draw.polygon(s, (222, 30, 78), P(lower))
        pygame.draw.polygon(s, (182, 12, 56), P(upper))
        pygame.draw.polygon(s, (96, 6, 30), P(upper), 1)
        pygame.draw.polygon(s, (96, 6, 30), P(lower), 1)
        pygame.draw.lines(s, (80, 4, 24), False, P([(-1, 0), (0, .09), (1, 0)]), max(1, w // 14))
        pygame.draw.ellipse(s, (255, 175, 195, 210), (int(cx - w * 0.30), int(cy + w * 0.28), int(w * 0.6), max(2, int(w * 0.2))))
        _ROM_CACHE[key] = s
    return s


def rom_draw_lips(x, y, w, alpha=255):
    s = rom_lips_surf(w)
    s.set_alpha(max(0, min(255, int(alpha))))
    screen.blit(s, s.get_rect(center=(int(x), int(y))))


def rom_bubble(x, y, txt, fill=(255, 238, 246), edge=(255, 110, 160)):
    img = F_XS.render(txt, True, (96, 20, 54))
    bw, bh = img.get_size()
    r = pygame.Rect(0, 0, bw + 18, bh + 10)
    r.midbottom = (int(x), int(y))
    r.clamp_ip(pygame.Rect(4, 4, W - 8, H - 8))
    pygame.draw.rect(screen, fill, r, border_radius=10)
    pygame.draw.rect(screen, edge, r, 2, border_radius=10)
    tx = max(r.left + 10, min(r.right - 10, int(x)))
    tail = [(tx - 6, r.bottom - 1), (tx + 6, r.bottom - 1), (tx, r.bottom + 9)]
    pygame.draw.polygon(screen, fill, tail)
    pygame.draw.lines(screen, edge, False, [tail[0], tail[2], tail[1]], 2)
    screen.blit(img, img.get_rect(center=r.center))


def rom_draw_note(x, y, col, alpha=255):
    pygame.draw.ellipse(screen, col, (int(x) - 5, int(y) - 3, 10, 7))
    pygame.draw.line(screen, col, (int(x) + 4, int(y)), (int(x) + 4, int(y) - 16), 2)
    pygame.draw.line(screen, col, (int(x) + 4, int(y) - 16), (int(x) + 10, int(y) - 11), 2)


def rom_draw_van(x, y, face, wheel, door):
    """Getaway van. x = centre, y = ground line, face = +1 nose to the right."""
    f = face
    body = (38, 40, 52)
    pygame.draw.rect(screen, (20, 20, 26), (int(x - 62), int(y - 62), 124, 52), border_radius=8)
    pygame.draw.rect(screen, body, (int(x - 60), int(y - 60), 120, 50), border_radius=8)
    pygame.draw.rect(screen, (60, 64, 80), (int(x - 60), int(y - 60), 120, 8), border_radius=6)
    cab_x = x + f * 38
    pygame.draw.rect(screen, (46, 50, 66), (int(cab_x - 22), int(y - 74), 44, 22), border_radius=6)
    pygame.draw.rect(screen, (120, 190, 235), (int(cab_x - 17 + f * 4), int(y - 70), 28, 14), border_radius=3)
    pygame.draw.circle(screen, (255, 235, 150), (int(x + f * 61), int(y - 34)), 5)
    pygame.draw.circle(screen, (200, 40, 40), (int(x - f * 61), int(y - 34)), 4)
    pygame.draw.rect(screen, (190, 35, 55), (int(x - 38), int(y - 46), 46, 7), border_radius=3)   # stripe
    if door > 0.01:
        pygame.draw.rect(screen, (8, 8, 12), (int(x - 6 - f * 6), int(y - 56), 26, 42))
    for wx in (x - 36, x + 36):
        pygame.draw.circle(screen, (14, 14, 16), (int(wx), int(y - 9)), 13)
        pygame.draw.circle(screen, (140, 140, 150), (int(wx), int(y - 9)), 6)
        a = wheel * f
        pygame.draw.line(screen, (30, 30, 36), (int(wx), int(y - 9)),
                         (int(wx + math.cos(a) * 6), int(y - 9 + math.sin(a) * 6)), 2)


def rom_draw_robber_figure(x, y, face, step, carrying=False):
    """Simple masked robber used in the kidnap cut-scene.  y = feet."""
    sw = math.sin(step) * 6
    pygame.draw.line(screen, (25, 25, 30), (int(x - 3), int(y - 22)), (int(x - 3 + sw), int(y)), 5)
    pygame.draw.line(screen, (25, 25, 30), (int(x + 3), int(y - 22)), (int(x + 3 - sw), int(y)), 5)
    pygame.draw.rect(screen, (46, 46, 56), (int(x - 9), int(y - 48), 18, 28), border_radius=4)
    pygame.draw.rect(screen, (190, 40, 50), (int(x - 9), int(y - 36), 18, 4))
    ax = x + face * 14
    pygame.draw.line(screen, (46, 46, 56), (int(x + face * 6), int(y - 42)), (int(ax), int(y - 34 if carrying else y - 28)), 4)
    pygame.draw.circle(screen, (226, 184, 150), (int(x), int(y - 56)), 9)
    pygame.draw.rect(screen, (14, 14, 18), (int(x - 9), int(y - 59), 18, 6))          # mask
    pygame.draw.rect(screen, (30, 30, 36), (int(x - 10), int(y - 67), 20, 7), border_radius=3)   # beanie
    pygame.draw.circle(screen, (255, 255, 255), (int(x + face * 3), int(y - 57)), 1)


def rom_veil(col, alpha):
    a = max(0, min(255, int(alpha) // 6 * 6))
    key = ("v", col, a)
    s = _ROM_CACHE.get(key)
    if s is None:
        s = pygame.Surface((W, H), pygame.SRCALPHA)
        s.fill((col[0], col[1], col[2], a))
        _ROM_CACHE[key] = s
    return s


def rom_draw_sparkle(x, y, r, col, alpha=255):
    pts = [(x, y - r), (x + r * 0.28, y - r * 0.28), (x + r, y), (x + r * 0.28, y + r * 0.28),
           (x, y + r), (x - r * 0.28, y + r * 0.28), (x - r, y), (x - r * 0.28, y - r * 0.28)]
    k = max(0.15, min(1.0, alpha / 255.0))
    c = (int(col[0] * k), int(col[1] * k), int(col[2] * k))
    pygame.draw.polygon(screen, c, [(int(a), int(b)) for a, b in pts])

