# ----------------------------------------------------------------- sound
def synth(dur, f0, f1, noise, vol):
    init = pygame.mixer.get_init()
    if not init or init[1] != -16:
        return None
    rate, _, ch = init
    n = int(rate * dur)
    buf = array("h")
    ph = 0.0
    for i in range(n):
        t = i / n
        ph += 2 * math.pi * (f0 + (f1 - f0) * t) / rate
        s = (math.sin(ph) * (1 - noise) + random.uniform(-1, 1) * noise) * (1 - t) ** 2 * vol
        v = int(max(-1, min(1, s)) * 32767)
        for _ in range(ch):
            buf.append(v)
    try:
        return pygame.mixer.Sound(buffer=buf.tobytes())
    except Exception:
        return None

