def play(name, vol=1.0):
    snd = SND.get(name)
    if snd:
        snd.set_volume(vol)
        snd.play()

def toggle_music():
    """Play/stop a user-supplied Attack on Titan audio file with P.

    If the expected file is not beside the game, open a file picker so the
    user can select their own MP3/OGG/WAV file instead of silently failing.
    """
    global MUSIC_PATH, MUSIC_STATUS
    if not AUDIO:
        try:
            pygame.mixer.init(frequency=44100, size=-16, channels=2, buffer=2048)
        except pygame.error as exc:
            MUSIC_STATUS = f"Audio unavailable: {exc}"
            print(MUSIC_STATUS)
            return False

    try:
        if pygame.mixer.music.get_busy():
            pygame.mixer.music.stop()
            MUSIC_STATUS = "Attack on Titan music: OFF"
            print(MUSIC_STATUS)
            return True

        # Reuse a selected file, or look for the conventional filename.
        if not MUSIC_PATH or not os.path.isfile(MUSIC_PATH):
            here = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
            candidates = [
                os.path.join(here, MUSIC_NAME_WEB),
                os.path.join(os.getcwd(), MUSIC_NAME_WEB),
                os.path.join(here, MUSIC_NAME),
                os.path.join(os.getcwd(), MUSIC_NAME),
                os.path.join(os.path.dirname(here), MUSIC_NAME),
            ]
            MUSIC_PATH = next((candidate for candidate in candidates if os.path.isfile(candidate)), None)

        if not MUSIC_PATH and WEB:
            MUSIC_STATUS = "No music found. Put attack_on_titan_op_1.ogg next to main.py and rebuild."
            print(MUSIC_STATUS)
            return False
        if not MUSIC_PATH:
            # P opens a chooser if the soundtrack has not been supplied.
            try:
                root = tk.Tk()
                root.withdraw()
                try:
                    root.attributes("-topmost", True)
                except tk.TclError:
                    pass
                selected = filedialog.askopenfilename(
                    parent=root,
                    title="Select your Attack on Titan intro music",
                    filetypes=[("Audio files", "*.mp3 *.ogg *.wav *.flac"), ("All files", "*.*")],
                )
                root.destroy()
            except Exception as exc:
                selected = ""
                print(f"Could not open the music file picker: {exc}")
            if not selected:
                MUSIC_STATUS = f"No song selected. Put {MUSIC_NAME} beside this game, then press P."
                print(MUSIC_STATUS)
                return False
            MUSIC_PATH = selected

        pygame.mixer.music.load(MUSIC_PATH)
        pygame.mixer.music.set_volume(0.60)
        pygame.mixer.music.play(-1)
        MUSIC_STATUS = f"Playing: {os.path.basename(MUSIC_PATH)} (press P to stop)"
        print(MUSIC_STATUS)
        return True
    except (pygame.error, OSError) as exc:
        MUSIC_STATUS = f"Could not play this audio file: {exc}"
        print(MUSIC_STATUS)
        # If an MP3 decoder is unavailable, allow choosing a compatible file.
        MUSIC_PATH = None
        return False


# ------------------------------------------------------------ art helpers
S = 4

def ii(*a):
    return tuple(int(v) for v in a)

def lerp(a, b, t):
    return a + (b - a) * t

def make_soldier(v):
    """Higher-detail procedural soldier base: cleaner proportions, richer shading, camo variation."""
    surf = pygame.Surface((60 * S, 76 * S), pygame.SRCALPHA)
    OL = (16, 16, 24)
    def rr(x, y, w, h, col, r=2, ol=1.0):
        pygame.draw.rect(surf, OL, ii((x - ol) * S, (y - ol) * S, (w + 2 * ol) * S, (h + 2 * ol) * S),
                         border_radius=int((r + ol) * S))
        pygame.draw.rect(surf, col, ii(x * S, y * S, w * S, h * S), border_radius=int(r * S))
    def el(x, y, w, h, col, ol=1.0):
        pygame.draw.ellipse(surf, OL, ii((x - ol) * S, (y - ol) * S, (w + 2 * ol) * S, (h + 2 * ol) * S))
        pygame.draw.ellipse(surf, col, ii(x * S, y * S, w * S, h * S))
    seed = sum(v.get("helm", (0, 0, 0))) + sum(v.get("pants", (0, 0, 0)))
    rng = random.Random(seed % 9973 + 11)
    # Legs with denser camo breakup
    for lx in (19, 31):
        rr(lx, 52, 11, 15, v["pants"], 2)
        for _ in range(7):
            cx, cy = lx + rng.uniform(0.5, 7), 53 + rng.uniform(0, 10)
            pygame.draw.ellipse(surf, rng.choice(v["camo"]), ii(cx * S, cy * S, 3.2 * S, 2.4 * S))
    # Boots with sole highlight
    for bx in (18, 31):
        rr(bx, 64, 13, 9, (32, 28, 28), 3)
        pygame.draw.line(surf, (70, 65, 60), ii((bx + 1) * S, 65 * S), ii((bx + 11) * S, 65 * S), max(1, S))
    # Torso vest + webbing
    rr(16, 34, 30, 24, v["vest"], 5)
    rr(19, 39, 9, 8, v["vest2"], 1, 0.6)
    rr(34, 39, 9, 8, v["vest2"], 1, 0.6)
    # Diagonal webbing strap with brass snaps
    pygame.draw.line(surf, (36, 36, 40), ii(18 * S, 36 * S), ii(44 * S, 55 * S), 3 * S)
    for k in range(7):
        cx, cy = 20 + k * 3.4, 37.5 + k * 2.5
        pygame.draw.circle(surf, OL, ii(cx * S, cy * S), int(2.4 * S))
        pygame.draw.circle(surf, (210, 165, 58), ii(cx * S, cy * S), int(1.7 * S))
    rr(16, 52, 30, 4, (46, 42, 38), 1, 0.6)
    # Arms
    for ax in (7, 45):
        rr(ax, 36, 11, 19, (68, 70, 78), 4)
        rr(ax, 36, 11, 6, (32, 32, 38), 3, 0.6)
    # Head
    el(14, 7, 32, 31, v["skin"])
    el(15, 27, 30, 12, v["beard"])
    # Mouth / teeth suggestion
    rr(24, 30.5, 14, 5, (240, 240, 240), 1, 0.8)
    for tx in (27.5, 31, 34.5):
        pygame.draw.line(surf, OL, ii(tx * S, 30.5 * S), ii(tx * S, 35.5 * S), int(0.7 * S))
    pygame.draw.line(surf, OL, ii(24 * S, 33 * S), ii(38 * S, 33 * S), int(0.7 * S))
    # Eyes
    el(19, 20, 10, 7, (255, 255, 255), 0.6)
    el(33, 20, 10, 7, (255, 255, 255), 0.6)
    pygame.draw.circle(surf, OL, ii(26 * S, 23.5 * S), int(2.0 * S))
    pygame.draw.circle(surf, OL, ii(36.5 * S, 23.5 * S), int(2.0 * S))
    # Eyebrows
    pygame.draw.polygon(surf, OL, [ii(17 * S, 17 * S), ii(29 * S, 21 * S), ii(29 * S, 23.5 * S), ii(17 * S, 19.5 * S)])
    pygame.draw.polygon(surf, OL, [ii(45 * S, 17 * S), ii(33 * S, 21 * S), ii(33 * S, 23.5 * S), ii(45 * S, 19.5 * S)])
    # Helmet
    el(10, 0, 40, 24, v["helm"], 1.2)
    pygame.draw.ellipse(surf, v["hi"], ii(15 * S, 2 * S, 16 * S, 7 * S))
    rr(10, 14, 40, 5, v["helm_d"], 2, 1.0)
    pygame.draw.circle(surf, (245, 245, 245), ii(30 * S, 8 * S), int(2.2 * S))
    pygame.draw.line(surf, OL, ii(13 * S, 19 * S), ii(16 * S, 29 * S), int(0.9 * S))
    pygame.draw.line(surf, OL, ii(47 * S, 19 * S), ii(44 * S, 29 * S), int(0.9 * S))
    # Neck scarf / collar
    rr(18, 35, 26, 5, v["scarf"], 2, 0.8)
    return pygame.transform.smoothscale(surf, (SPR_W, SPR_H))

def gun_finish(surf, seed=0):
    """Studio-style finishing pass for the weapon art: vertical light falloff, top-edge rim light,
    dark under-edge, specular sheen, micro-scratches and a soft contact shadow."""
    size = surf.get_size()
    K = 4
    m = pygame.mask.from_surface(surf, 24)
    white = m.to_surface(setcolor=(255, 255, 255, 255), unsetcolor=(0, 0, 0, 255))
    # 1) light falloff (bright top, deeper belly)
    grad = pygame.Surface(size)
    for y in range(size[1]):
        t = y / float(size[1])
        v = 255 if t < 0.22 else int(255 - 85 * (t - 0.22) / 0.78)
        pygame.draw.line(grad, (v, v, min(255, v + 6)), (0, y), (size[0], y))
    surf.blit(grad, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
    # 2) rim light on upward-facing edges, dark line on downward-facing edges
    top = white.copy()
    top.blit(white, (0, K), special_flags=pygame.BLEND_RGB_SUB)
    top.fill((120, 130, 142), special_flags=pygame.BLEND_RGB_MULT)
    surf.blit(top, (0, 0), special_flags=pygame.BLEND_RGB_ADD)
    bot = white.copy()
    bot.blit(white, (0, -K), special_flags=pygame.BLEND_RGB_SUB)
    bot.fill((78, 78, 84), special_flags=pygame.BLEND_RGB_MULT)
    surf.blit(bot, (0, 0), special_flags=pygame.BLEND_RGB_SUB)
    # 3) specular sheen + scratches (confined to the weapon by the mask)
    rects = m.get_bounding_rects()
    if rects:
        bb = rects[0].unionall(rects[1:])
        band = pygame.Surface(size)
        sy = bb.top + int(bb.h * 0.30)
        for i in range(K * 2):
            f = 1.0 - abs(i - K) / float(K)
            c = int(58 * f)
            pygame.draw.line(band, (c, c + 3, c + 6), (bb.left, sy + i - K), (bb.right, sy + i - K))
        rng = random.Random(seed * 31 + 7)
        for _ in range(16):
            x0 = rng.randint(bb.left, max(bb.left + 1, bb.right - 30))
            y0 = rng.randint(bb.top, max(bb.top + 1, bb.bottom - 4))
            pygame.draw.line(band, (46, 50, 56), (x0, y0), (x0 + rng.randint(6, 26), y0 + rng.randint(-3, 3)), 1)
        band.blit(white, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        surf.blit(band, (0, 0), special_flags=pygame.BLEND_RGB_ADD)
    # 4) contact shadow, then clean supersample down to game size
    out = pygame.Surface(size, pygame.SRCALPHA)
    out.blit(m.to_surface(setcolor=(0, 0, 0, 70), unsetcolor=(0, 0, 0, 0)), (int(1.0 * K), int(1.6 * K)))
    out.blit(surf, (0, 0))
    return pygame.transform.smoothscale(out, (84, 30))


def make_gun(wtype="ar", weapon_name="M4"):
    """High-detail side-view weapon artwork, rendered large then downscaled cleanly."""
    # Larger source canvas gives the weapon a more convincing silhouette at game scale.
    K = 4
    Wg, Hg = 96, 34
    surf = pygame.Surface((Wg*K, Hg*K), pygame.SRCALPHA)
    def pt(x, y):
        return (int(round(x*K)), int(round(y*K)))
    def rect(x, y, w, h):
        return pygame.Rect(int(round(x*K)), int(round(y*K)), max(1,int(round(w*K))), max(1,int(round(h*K))))
    def line(col, a, b, width=1):
        pygame.draw.line(surf, col, pt(*a), pt(*b), max(1,int(round(width*K))))
    def poly(col, points):
        pygame.draw.polygon(surf, col, [pt(*q) for q in points])
    def rr(col, x, y, w, h, rad=1):
        pygame.draw.rect(surf, col, rect(x,y,w,h), border_radius=max(1,int(rad*K)))
    def ell(col, x, y, w, h):
        pygame.draw.ellipse(surf, col, rect(x,y,w,h))

    # Common layered palette: near-black outline, parkerized steel and edge glints.
    outline=(12,16,21); shadow=(25,31,39); metal=(65,75,86); steel=(111,123,135)
    hi=(191,201,208); edge=(226,232,235); polymer=(42,49,54); polymer_hi=(78,86,88)
    accent=(202,157,67); glass=(55,147,177)

    # Weapon-specific lower receiver, stock and barrel profile.
    if wtype in ("ar", "lmg"):
        # Collapsible stock and cheek weld.
        poly(outline, [(3,10),(14,9),(18,12),(17,19),(12,21),(5,18)])
        poly(polymer, [(4,11),(13,10),(16,13),(15,18),(11,19),(6,17)])
        line(polymer_hi,(6,12),(12,12),1)
        rr(outline, 14,9,45,12,2); rr(metal,15,10,42,9,2)
        rr(steel,17,10,30,2,1); line(hi,(18,11),(43,11),0.7)
        # Handguard, vent slots and barrel.
        rr(outline, 42,8,21,13,2); rr(polymer,43,9,19,11,2)
        for x in (46,50,54,58):
            rr(shadow,x,10,2,6,0.5); line(polymer_hi,(x+0.4,10.5),(x+0.4,15.5),0.5)
        rr(outline, 60,11,28 if wtype=="lmg" else 25,4,1)
        rr(metal, 62,11.5,24 if wtype=="lmg" else 21,2.5,1)
        line(hi,(64,12),(83 if wtype=="lmg" else 81,12),0.5)
        # Magazine, trigger guard and grip.
        poly(outline,[(28,18),(40,18),(39,30),(35,32),(29,29)])
        poly(polymer,[(29,19),(39,19),(38,29),(35,30),(30,28)])
        for y in (21,24,27): line(polymer_hi,(30,y),(38,y-0.5),0.7)
        poly(outline,[(20,18),(28,18),(26,26),(22,26)])
        poly(polymer,[(21,19),(27,19),(25,24),(23,24)])
        # Picatinny top rail.
        rr(outline, 27,6,35,3,0.5)
        for x in range(29,61,3): line(steel,(x,6),(x,8),0.8)
        # Red-dot optic, with a tiny glass reflection.
        rr(outline, 34,2,13,5,1); rr(metal,35,2.5,11,3,1)
        rr(glass,38,3,5,1,0.4); line(edge,(38,3),(41,3),0.5)
        if wtype=="lmg":
            # Box magazine and a heavier barrel shroud distinguish the LMG.
            rr(outline, 42,17,12,11,1); rr(metal,43,18,10,9,1)
            for y in (20,23,26): line(steel,(44,y),(52,y),0.7)
            rr(outline, 65,8,17,3,1); rr(metal,66,8.5,15,1.5,0.5)
    elif wtype=="smg":
        poly(outline,[(6,11),(17,10),(21,13),(18,19),(9,20),(5,17)])
        poly(polymer,[(7,12),(16,11),(19,14),(17,18),(10,18),(7,16)])
        rr(outline,16,10,36,11,2); rr(metal,17,11,34,8,2)
        rr(steel,19,11,22,2,1); line(hi,(20,12),(39,12),0.5)
        rr(outline,48,12,38,4,1); rr(metal,50,12.5,34,2.5,1)
        rr(outline,31,7,23,4,1); rr(polymer,32,8,21,2,0.5)
        for x in (34,38,42,46): line(polymer_hi,(x,8),(x,9.5),0.6)
        poly(outline,[(25,19),(34,19),(33,30),(29,32),(26,29)])
        poly(polymer,[(26,20),(33,20),(32,29),(29,30),(27,28)])
        for y in (22,25,28): line(polymer_hi,(27,y),(32,y-0.5),0.6)
        rr(outline,22,6,12,4,1); rr(metal,23,6.5,10,2,0.5)
    elif wtype=="sniper":
        # Long precision barrel, adjustable stock and magnified optic.
        poly(outline,[(2,12),(16,10),(24,12),(23,20),(16,22),(4,19)])
        poly(polymer,[(4,13),(16,11),(22,13),(21,19),(15,20),(5,18)])
        rr(outline,17,10,39,12,2); rr(metal,18,11,37,9,2)
        rr(steel,20,11,25,2,1); line(hi,(21,12),(43,12),0.6)
        rr(outline,49,12,42,3,1); rr(metal,51,12.5,37,2,0.5)
        line(hi,(53,13),(87,13),0.5)
        # Large scope with mounts and two glass rings.
        rr(outline,29,3,26,7,2); rr(metal,31,4,22,5,2)
        ell(outline,28,2,6,9); ell(glass,30,3,3,7); line(edge,(31,4),(32,5),0.7)
        ell(outline,51,2,6,9); ell(glass,52,3,3,7)
        rr(outline,34,9,14,3,1); rr(steel,35,9.5,12,1.5,0.5)
        poly(outline,[(26,20),(36,20),(34,30),(30,32),(27,29)])
        poly(polymer,[(27,21),(35,21),(33,29),(30,30),(28,28)])
        for y in (23,26,28): line(polymer_hi,(28,y),(33,y-0.5),0.6)
        poly(outline,[(18,19),(25,19),(23,25),(19,25)])
        poly(polymer,[(19,20),(24,20),(22,23),(20,23)])
        rr(outline,43,20,8,3,1); line(steel,(44,21),(50,21),0.5)
    elif wtype=="shotgun":
        poly(outline,[(3,11),(15,10),(21,13),(19,20),(10,21),(4,18)])
        poly((94,69,48),[(5,12),(15,11),(19,14),(17,18),(10,19),(6,17)])
        rr(outline,16,10,27,11,2); rr((91,78,61),17,11,25,8,2)
        line((169,143,112),(19,12),(39,12),0.6)
        # Twin barrel bands and dark circular muzzle end.
        rr(outline,39,9,47,5,1); rr(metal,41,10,43,3,1)
        rr(steel,44,10.5,37,1,0.5)
        rr(outline,42,16,43,4,1); rr((85,74,59),44,16.5,39,3,1)
        for x in (47,58,69,78): line((39,42,43),(x,16),(x,19),0.7)
        poly(outline,[(23,19),(32,19),(31,30),(27,32),(24,29)])
        poly((55,47,38),[(24,20),(31,20),(30,29),(27,30),(25,28)])
        for y in (23,26,28): line((144,111,80),(25,y),(30,y-0.5),0.6)
        rr(outline,25,6,14,4,1); rr(metal,26,6.5,12,2,0.5)
    elif wtype=="pistol":
        # Compact slide with serrations, ejection port, trigger guard and textured grip.
        rr(outline,20,8,43,10,2); rr(metal,21,9,40,7,2)
        rr(steel,23,9,31,2,1); line(hi,(24,10),(50,10),0.5)
        rr(shadow,45,10,9,3,0.5); rr(metal,46,10.5,7,2,0.5)
        for x in (55,58,61): line(outline,(x,9),(x,13),0.8)
        rr(outline,58,10,31,4,1); rr(metal,60,10.5,27,2.5,1)
        poly(outline,[(27,17),(41,17),(38,31),(34,33),(29,30)])
        poly(polymer,[(28,18),(40,18),(37,30),(34,31),(30,29)])
        for y in (21,24,27): line(polymer_hi,(30,y),(38,y-1),0.8)
        # trigger guard is visibly separated from the grip
        pygame.draw.arc(surf, outline, rect(38,15,12,9), math.pi, math.tau, max(1,K))
        line(outline,(44,16),(44,21),1)
        rr(outline,29,5,12,3,1); rr(metal,30,5.5,10,1.5,0.5)
    else:
        rr(outline,14,10,46,11,2); rr(metal,15,11,44,8,2)
        rr(outline,58,12,31,4,1); rr(metal,60,12.5,27,2.5,1)
        poly(outline,[(25,19),(35,19),(33,30),(29,32),(26,29)])
        poly(polymer,[(26,20),(34,20),(32,29),(29,30),(27,28)])

    # Muzzle crown, bore, sling loops, selector and small fasteners add a machined finish.
    rr(outline,85 if wtype!="sniper" else 87,9,7,8,1)
    rr(steel,86 if wtype!="sniper" else 88,10,5,6,1)
    ell((7,10,14),88 if wtype!="sniper" else 90,11,3,4)
    ell((116,125,132),89 if wtype!="sniper" else 91,12,1,2)
    pygame.draw.circle(surf, accent, pt(19,16), max(1,int(0.9*K)))
    pygame.draw.circle(surf, outline, pt(19,16), max(1,int(0.45*K)))
    # Small sling attachment and under-rail details.
    pygame.draw.arc(surf, steel, rect(13,20,8,5), 0, math.pi, max(1,int(0.7*K)))
    line((7,9,13),(13,22),(20,22),0.6)
    # Fine engraved highlight along the upper contour.
    line((220,226,229),(20,8),(43,8),0.5)
    # Per-model signature parts: every named firearm gets its own silhouette,
    # furniture, optic, muzzle, and magazine profile instead of sharing a generic class sprite.
    model_seed = sum((i + 1) * ord(ch) for i, ch in enumerate(weapon_name))
    model_rng = random.Random(model_seed)
    model_colors = [(184, 196, 205), (202, 157, 67), (82, 180, 166),
                    (174, 104, 70), (125, 155, 205), (190, 190, 155),
                    (210, 90, 80), (130, 120, 190)]
    model_accent = model_colors[model_seed % len(model_colors)]
    # Model-specific top attachment: optic, scope, carry handle or raised iron sights.
    attachment = model_seed % 4
    if wtype != "pistol":
        if attachment == 0:
            rr(outline, 35, 1, 17, 6, 1); rr(model_accent, 37, 2, 13, 3, 1)
            line(edge, (39, 3), (47, 3), 0.6)
        elif attachment == 1:
            rr(outline, 31, 1, 23, 7, 2); rr(metal, 33, 2, 19, 4, 2)
            ell(glass, 35, 2, 5, 4); ell(glass, 45, 2, 5, 4)
        elif attachment == 2:
            poly(outline, [(29, 7), (32, 1), (50, 1), (54, 7)])
            line(hi, (33, 3), (49, 3), 0.7)
        else:
            rr(outline, 38, 2, 8, 5, 1); rr(model_accent, 40, 3, 4, 2, 0.5)
    # Coloured model plate, distinct vent pattern, and a unique magazine shape.
    rr(outline, 43, 14, 8, 3, 0.7)
    rr(model_accent, 44, 14.5, 6, 1.5, 0.5)
    for slot in range(2 + model_seed % 4):
        sx = 45 + slot * 2
        line(model_accent, (sx, 10), (sx, 12.5), 0.45)
    if wtype in ("ar", "smg", "lmg"):
        mag_style = model_seed % 3
        if mag_style == 0:
            poly(outline, [(29, 19), (40, 19), (39, 31), (35, 33), (30, 29)])
            poly(model_accent, [(31, 21), (38, 21), (37, 29), (34, 30), (32, 28)])
        elif mag_style == 1:
            poly(outline, [(30, 19), (39, 19), (42, 28), (39, 31), (32, 29)])
            poly(model_accent, [(32, 21), (38, 21), (40, 27), (38, 29), (34, 28)])
        else:
            rr(outline, 30, 19, 12, 12, 1); rr(model_accent, 32, 21, 8, 8, 1)
        # Unique handguard cut-outs and muzzle device.
        for slot in range(3 + model_seed % 3):
            sx = 45 + slot * 3
            line(model_accent, (sx, 10), (sx, 16), 0.55)
        rr(outline, 84 + model_seed % 4, 9, 5, 7, 1)
        rr(model_accent, 85 + model_seed % 4, 10, 3, 5, 0.5)
    elif wtype == "pistol":
        for slot in range(3 + model_seed % 3):
            sx = 29 + slot * 2
            line(model_accent, (sx, 20), (sx - 1, 28), 0.6)
        rr(model_accent, 47, 9, 5, 2, 0.5)
    elif wtype == "shotgun":
        rr(outline, 43, 15, 42, 6, 1)
        rr(model_accent, 47, 16, 33, 3, 1)
        for sx in (51, 61, 71, 81):
            line(edge, (sx, 16), (sx, 18), 0.5)
    elif wtype == "sniper":
        rr(outline, 31, 1, 25, 8, 2)
        rr(model_accent, 34, 3, 19, 4, 2)
        line(edge, (37, 4), (49, 4), 0.6)
        # Bipod legs distinguish precision rifles at gameplay scale.
        line(steel, (68, 16), (65, 24), 1)
        line(steel, (75, 16), (78, 24), 1)
    return gun_finish(surf, model_seed)

