# =====================================================================================
# SURVEY CORPS SCOUT - Attack on Titan style player look (fully procedural, 4x supersampled)
# Articulated body (run cycle, torso lean, 2-bone IK arms), physics cape, ODM gear,
# grapple wires, gas steam, afterimages, arc/spin blade slashes, blinking eyes.
# =====================================================================================
AOT_K = 4
AOT_CW, AOT_CH, AOT_FEET = 150, 140, 112     # local canvas (1x px) and the feet line inside it
AOT_SC = 1.3                                 # Scout is drawn 30% larger so he towers over the bots
AOT_OW, AOT_OH, AOT_OF = int(AOT_CW * AOT_SC), int(AOT_CH * AOT_SC), int(round(AOT_FEET * AOT_SC))

def aot_ik(sh, hand, l1, l2, down=True):
    """Two-bone IK: returns (elbow, reachable_hand) with fixed bone lengths."""
    dx, dy = hand[0] - sh[0], hand[1] - sh[1]
    d = min(max(0.001, math.hypot(dx, dy)), l1 + l2 - 0.05)
    base = math.atan2(dy, dx)
    c = max(-1.0, min(1.0, (l1 * l1 + d * d - l2 * l2) / (2 * l1 * d)))
    a = math.acos(c)
    e1 = (sh[0] + math.cos(base + a) * l1, sh[1] + math.sin(base + a) * l1)
    e2 = (sh[0] + math.cos(base - a) * l1, sh[1] + math.sin(base - a) * l1)
    pick = e1 if (e1[1] >= e2[1]) == down else e2
    return pick, (sh[0] + math.cos(base) * d, sh[1] + math.sin(base) * d)

def aot_leg(hip, th, kf, l1=14.5, l2=14.0):
    """Hip -> knee -> ankle. th = thigh swing from vertical, kf = knee flexion (radians)."""
    knee = (hip[0] + math.sin(th) * l1, hip[1] + math.cos(th) * l1)
    sh = th - kf
    ankle = (knee[0] + math.sin(sh) * l2, knee[1] + math.cos(sh) * l2)
    return knee, ankle, sh

def aot_slash_theta(u, n):
    """Blade angle (forward-local radians) at slash progress u (0..1). Odd n = arc, even n = spin."""
    e = 1.0 - (1.0 - max(0.0, min(1.0, u))) ** 2.2
    if n % 2:
        return math.radians(-125 + 190 * e), False
    return math.radians(-40) + math.tau * e, True

def aot_lerp_col(a, b, t):
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))

def aot_limb(surf, pts, w, col, ol=(30, 22, 20), hi=None):
    K = AOT_K
    P = [(int(x * K), int(y * K)) for x, y in pts]
    ow = int((w + 1.7) * K)
    for i in range(len(P) - 1):
        pygame.draw.line(surf, ol, P[i], P[i + 1], ow)
    for p in P:
        pygame.draw.circle(surf, ol, p, ow // 2)
    cw = int(w * K)
    for i in range(len(P) - 1):
        pygame.draw.line(surf, col, P[i], P[i + 1], cw)
    for p in P:
        pygame.draw.circle(surf, col, p, cw // 2)
    if hi:
        off = int(w * K * 0.2)
        for i in range(len(P) - 1):
            pygame.draw.line(surf, hi, (P[i][0] - off, P[i][1] - off), (P[i + 1][0] - off, P[i + 1][1] - off),
                             max(1, int(w * K * 0.22)))

def aot_poly(surf, pts, col, ol=None):
    K = AOT_K
    P = [(int(x * K), int(y * K)) for x, y in pts]
    pygame.draw.polygon(surf, col, P)
    if ol:
        pygame.draw.polygon(surf, ol, P, max(1, int(0.9 * K)))

def aot_ell(surf, cx, cy, rx, ry, col, ol=None):
    K = AOT_K
    if ol:
        pygame.draw.ellipse(surf, ol, (int((cx - rx - 0.8) * K), int((cy - ry - 0.8) * K),
                                       int((2 * rx + 1.6) * K), int((2 * ry + 1.6) * K)))
    pygame.draw.ellipse(surf, col, (int((cx - rx) * K), int((cy - ry) * K), int(2 * rx * K), int(2 * ry * K)))

def aot_line(surf, a, b, w, col):
    K = AOT_K
    pygame.draw.line(surf, col, (int(a[0] * K), int(a[1] * K)), (int(b[0] * K), int(b[1] * K)), max(1, int(w * K)))

def aot_blade(surf, base, ang, length=30.0, glint=0.0):
    """ODM blade: steel edge, bright spine, guard and black grip."""
    ca, sa = math.cos(ang), math.sin(ang)
    nx, ny = -sa, ca
    tip = (base[0] + ca * length, base[1] + sa * length)
    mid = (base[0] + ca * length * 0.8, base[1] + sa * length * 0.8)
    pts = [(base[0] + ca * 3 + nx * 1.6, base[1] + sa * 3 + ny * 1.6), (mid[0] + nx * 1.7, mid[1] + ny * 1.7),
           tip, (base[0] + ca * 3 - nx * 1.0, base[1] + sa * 3 - ny * 1.0)]
    aot_poly(surf, pts, (212, 224, 238), (34, 40, 52))
    aot_line(surf, (base[0] + ca * 4 + nx * 0.5, base[1] + sa * 4 + ny * 0.5), (tip[0] - ca * 1.6, tip[1] - sa * 1.6),
             0.7, (255, 255, 255))
    if glint > 0:
        gx = base[0] + ca * length * (0.2 + 0.75 * glint)
        gy = base[1] + sa * length * (0.2 + 0.75 * glint)
        pygame.draw.circle(surf, (255, 255, 255), (int(gx * AOT_K), int(gy * AOT_K)), int(1.7 * AOT_K))
    aot_line(surf, (base[0] + nx * 3.3, base[1] + ny * 3.3), (base[0] - nx * 3.3, base[1] - ny * 3.3), 1.7, (26, 26, 32))
    aot_line(surf, base, (base[0] - ca * 5.5, base[1] - sa * 5.5), 2.4, (22, 17, 15))

def aot_state_new():
    return {"wires": [], "trail": [], "slash": 0, "slash_n": 0, "cape": None, "was_air": False,
            "vy_hist": 0.0, "blink": 0, "phase": 0.0, "lean": 0.0, "last_img": None, "geo": None}

def appearance_rect(i):
    """Shared layout for the appearance menu (6 columns) so drawing and clicking always agree."""
    return pygame.Rect(34 + (i % 6) * 202, 92 + (i // 6) * 118, 190, 108)


