def make_black_op_bot(main, highlight, seed=0):
    """BLACK OP BOT — Human Operator Unit (reference sheet style).
    Beret + NVG, plate carrier, desert camo, backpack, combat boots.
    Colourway from (main, highlight) so each appearance stays unique."""
    K = S
    surf = pygame.Surface((60 * K, 76 * K), pygame.SRCALPHA)
    OL = (18, 16, 14)
    rng = random.Random((sum(main) * 17 + sum(highlight) * 31 + seed) % 9973 + 7)

    def clamp_col(c):
        return tuple(max(0, min(255, int(v))) for v in c)
    def shade(c, f):
        return clamp_col((c[0] * f, c[1] * f, c[2] * f))
    def mix(a, b, t):
        return clamp_col((a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t))

    camo_base = mix(main, (120, 110, 70), 0.35)
    camo_mid = mix(main, highlight, 0.4)
    camo_hi = mix(highlight, (200, 185, 130), 0.3)
    camo_dk = shade(camo_base, 0.55)
    camo_set = [camo_base, camo_mid, camo_hi, camo_dk, mix(camo_base, (90, 100, 60), 0.5)]
    vest_col = shade(camo_base, 0.72)
    vest_hi = mix(vest_col, (180, 170, 130), 0.35)
    boot_col = mix(camo_dk, (70, 60, 40), 0.4)
    boot_hi = mix(boot_col, (140, 120, 80), 0.4)
    skin, skin_sh = (225, 178, 142), (190, 145, 115)
    beret = mix(main, (70, 85, 50), 0.55)
    beret_d = shade(beret, 0.65)
    nvg, nvg_lens, nvg_glow = (28, 30, 34), (40, 55, 40), (60, 200, 80)
    pouch = shade(vest_col, 0.8)
    pack = shade(camo_base, 0.6)

    def rr(x, y, w, h, col, rad=2, ol=1.0):
        pygame.draw.rect(surf, OL, ii((x - ol) * K, (y - ol) * K, (w + 2 * ol) * K, (h + 2 * ol) * K),
                         border_radius=max(1, int((rad + ol) * K)))
        pygame.draw.rect(surf, col, ii(x * K, y * K, w * K, h * K), border_radius=max(1, int(rad * K)))
    def el(x, y, w, h, col, ol=1.0):
        pygame.draw.ellipse(surf, OL, ii((x - ol) * K, (y - ol) * K, (w + 2 * ol) * K, (h + 2 * ol) * K))
        pygame.draw.ellipse(surf, col, ii(x * K, y * K, w * K, h * K))
    def blob_camo(x, y, w, h, n=8):
        for _ in range(n):
            cx = x + rng.uniform(0.5, max(0.6, w - 1))
            cy = y + rng.uniform(0.5, max(0.6, h - 1))
            pygame.draw.ellipse(surf, rng.choice(camo_set),
                                ii(cx * K, cy * K, rng.uniform(1.6, 3.8) * K, rng.uniform(1.2, 2.8) * K))

    for lx in (18, 32):
        rr(lx, 50, 12, 16, camo_base, 3)
        blob_camo(lx, 50, 12, 16, 9)
        rr(lx + 1, 56, 10, 5, vest_col, 2, 0.5)
    for bx in (17, 31):
        rr(bx, 64, 14, 10, boot_col, 3)
        pygame.draw.rect(surf, shade(boot_col, 0.5), ii((bx + 1) * K, 71 * K, 12 * K, 3 * K),
                         border_radius=max(1, int(1.5 * K)))
        for ly in (66, 68, 70):
            pygame.draw.line(surf, boot_hi, ii((bx + 3) * K, ly * K), ii((bx + 11) * K, ly * K), max(1, K // 2))
        for _ in range(3):
            pygame.draw.circle(surf, (255, 255, 255),
                               ii((bx + rng.uniform(2, 11)) * K, (65 + rng.uniform(1, 7)) * K),
                               max(1, int(0.55 * K)))
    rr(40, 32, 12, 20, pack, 3)
    rr(41, 34, 10, 6, shade(pack, 1.15), 2, 0.5)
    pygame.draw.line(surf, shade(pack, 0.4), ii(42 * K, 42 * K), ii(50 * K, 42 * K), max(1, K))
    pygame.draw.line(surf, shade(pack, 0.4), ii(42 * K, 46 * K), ii(50 * K, 46 * K), max(1, K))
    pygame.draw.rect(surf, (40, 42, 48), ii(48 * K, 28 * K, 2 * K, 6 * K))
    pygame.draw.circle(surf, (60, 200, 90), ii(49 * K, 27 * K), max(1, int(1.2 * K)))
    rr(15, 32, 30, 20, camo_base, 4)
    blob_camo(15, 32, 30, 20, 14)
    rr(16, 33, 28, 18, vest_col, 3)
    rr(18, 34, 24, 8, vest_hi, 2, 0.5)
    for px in (18, 26, 34):
        rr(px, 43, 7, 8, pouch, 1, 0.6)
        pygame.draw.line(surf, shade(pouch, 0.5), ii((px + 1) * K, 47 * K), ii((px + 6) * K, 47 * K), max(1, K // 2))
    rr(14, 38, 4, 10, pouch, 1, 0.5)
    rr(42, 38, 4, 10, pouch, 1, 0.5)
    pygame.draw.rect(surf, (40, 42, 48), ii(27 * K, 40 * K, 6 * K, 3 * K), border_radius=max(1, K))
    pygame.draw.rect(surf, (180, 160, 60), ii(28 * K, 40.5 * K, 4 * K, 2 * K))
    rr(15, 50, 30, 4, (40, 38, 34), 1, 0.6)
    pygame.draw.rect(surf, (160, 140, 50), ii(27 * K, 50.5 * K, 6 * K, 3 * K))
    for ax in (5, 44):
        rr(ax, 34, 12, 18, camo_base, 4)
        blob_camo(ax, 34, 12, 18, 6)
        rr(ax, 48, 12, 6, (32, 30, 28), 2, 0.5)
        rr(ax, 33, 12, 5, vest_col, 2, 0.5)
    rr(24, 28, 12, 6, skin_sh, 2, 0.5)
    el(16, 8, 28, 26, skin)
    el(18, 24, 24, 10, skin_sh)
    pygame.draw.polygon(surf, shade(skin, 0.88), [ii(30 * K, 18 * K), ii(27 * K, 26 * K), ii(33 * K, 26 * K)])
    el(20, 16, 8, 6, (250, 250, 250), 0.5)
    el(32, 16, 8, 6, (250, 250, 250), 0.5)
    pygame.draw.circle(surf, (30, 40, 50), ii(25 * K, 19 * K), int(2.2 * K))
    pygame.draw.circle(surf, (30, 40, 50), ii(37 * K, 19 * K), int(2.2 * K))
    pygame.draw.circle(surf, (220, 230, 240), ii(24.3 * K, 18.3 * K), max(1, int(0.8 * K)))
    pygame.draw.circle(surf, (220, 230, 240), ii(36.3 * K, 18.3 * K), max(1, int(0.8 * K)))
    pygame.draw.line(surf, (50, 35, 30), ii(19 * K, 15 * K), ii(28 * K, 16 * K), max(1, int(1.2 * K)))
    pygame.draw.line(surf, (50, 35, 30), ii(32 * K, 16 * K), ii(41 * K, 15 * K), max(1, int(1.2 * K)))
    pygame.draw.line(surf, (90, 55, 50), ii(25 * K, 29 * K), ii(35 * K, 29 * K), max(1, int(1.1 * K)))
    el(12, 1, 36, 16, beret, 1.2)
    pygame.draw.ellipse(surf, beret_d, ii(14 * K, 8 * K, 32 * K, 8 * K))
    pygame.draw.ellipse(surf, mix(beret, (180, 190, 120), 0.35), ii(18 * K, 2 * K, 14 * K, 5 * K))
    pygame.draw.circle(surf, highlight, ii(38 * K, 7 * K), max(1, int(2.0 * K)))
    pygame.draw.circle(surf, shade(highlight, 0.5), ii(38 * K, 7 * K), max(1, int(1.0 * K)))
    rr(22, 9, 16, 4, nvg, 1, 0.5)
    el(18, 7, 10, 9, nvg, 0.8)
    el(19.5, 8.5, 7, 6, nvg_lens, 0.3)
    pygame.draw.circle(surf, nvg_glow, ii(23 * K, 11.5 * K), max(1, int(1.5 * K)))
    el(32, 7, 10, 9, nvg, 0.8)
    el(33.5, 8.5, 7, 6, nvg_lens, 0.3)
    pygame.draw.circle(surf, nvg_glow, ii(37 * K, 11.5 * K), max(1, int(1.5 * K)))
    pygame.draw.line(surf, (30, 30, 34), ii(16 * K, 12 * K), ii(12 * K, 18 * K), max(1, K))
    pygame.draw.line(surf, (30, 30, 34), ii(44 * K, 12 * K), ii(48 * K, 18 * K), max(1, K))
    el(10, 16, 7, 9, (40, 42, 48), 0.6)
    el(43, 16, 7, 9, (40, 42, 48), 0.6)
    return pygame.transform.smoothscale(surf, (SPR_W, SPR_H))


def make_appearance_sprite(index):
    """Every appearance EXCEPT Survey Corps Scout uses BLACK OP BOT look.
    AOT keeps its dedicated procedural renderer."""
    name, main, highlight, accessory = APPEARANCES[index]
    if accessory == "aot":
        dark = tuple(max(0, c // 3) for c in main)
        pale = (235, 205, 175)
        palette = dict(helm=main, hi=highlight, helm_d=dark, vest=dark,
                       vest2=main, skin=pale, beard=(35, 25, 30),
                       scarf=highlight, pants=main,
                       camo=[dark, main, highlight])
        return make_soldier(palette)
    if BLACKOP_BASE:
        return blackop_preview(index)
    return make_black_op_bot(main, highlight, seed=index * 97 + 13)



def build_art():
    global GUN_CACHE, GUN_FLIP_CACHE
    APPEARANCE_SPR.clear()
    for ai in range(len(APPEARANCES)):
        spr = make_appearance_sprite(ai)
        APPEARANCE_SPR[ai] = (spr, pygame.transform.flip(spr, True, False))
    base = make_soldier(PLAYER_V)
    SPR["player"] = (base, pygame.transform.flip(base, True, False))
    for i, v in enumerate(BOT_VS):
        b = make_soldier(v)
        SPR["b%d" % i] = (b, pygame.transform.flip(b, True, False))
    # Keep legacy keys safe if any code still references only 0-2.
    for i in range(len(BOT_VS), 6):
        if "b%d" % i not in SPR:
            SPR["b%d" % i] = SPR["b0"]
    # Cache a separate illustrated sprite for every firearm model, not merely its class.
    for weapon_name, spec in WEAPONS.items():
        if spec.get("cat") not in ("primary", "secondary"):
            continue
        t = spec.get("type", "ar")
        g = make_gun(t, weapon_name)
        GUN_CACHE[weapon_name] = g
        GUN_FLIP_CACHE[weapon_name] = pygame.transform.flip(g, False, True)
        display_name = spec.get("name", weapon_name)
        GUN_CACHE[display_name] = g
        GUN_FLIP_CACHE[display_name] = pygame.transform.flip(g, False, True)
    # Safe class fallbacks for special cases and older code paths.
    for t in ("ar", "smg", "sniper", "shotgun", "pistol", "lmg"):
        fallback = next((GUN_CACHE[n] for n, spec in WEAPONS.items()
                         if spec.get("type") == t and spec.get("cat") in ("primary", "secondary")), None)
        if fallback is not None:
            GUN_CACHE[t] = fallback
            GUN_FLIP_CACHE[t] = pygame.transform.flip(fallback, False, True)

# ------------------------------------------------------------ beautiful girl sprite
GIRL_SPR = {}

def make_girl(dress, dress_hi):
    K = 6
    Wd, Hd = 46, 72
    surf = pygame.Surface((Wd * K, Hd * K), pygame.SRCALPHA)
    cx = 23
    OL = (40, 20, 24)
    skin, skin_sh, skin_hi = (250, 212, 188), (226, 166, 140), (255, 230, 212)
    hair_d, hair_m, hair_l = (62, 26, 20), (110, 48, 30), (190, 112, 60)

    def P(pts):
        return [(x * K, y * K) for x, y in pts]
    def poly(col, pts):
        pygame.draw.polygon(surf, col, P(pts))
    def E(col, x, y, w, h):
        pygame.draw.ellipse(surf, col, ii(x * K, y * K, w * K, h * K))
    def C(col, x, y, r):
        pygame.draw.circle(surf, col, ii(x * K, y * K), max(1, int(r * K)))
    def L(col, pts, w):
        pygame.draw.lines(surf, col, False, P(pts), max(1, int(w * K)))

    # ---- very long flowing back hair
    E(hair_d, cx - 14, 1.5, 28, 34)
    for s in (-1, 1):
        poly(hair_d, [(cx + s * 12, 14), (cx + s * 15.5, 30), (cx + s * 14.5, 48),
                      (cx + s * 12, 60), (cx + s * 8.5, 64), (cx + s * 7.5, 48),
                      (cx + s * 8, 40), (cx + s * 9.5, 26)])
        L(hair_m, [(cx + s * 12.5, 18), (cx + s * 14, 32), (cx + s * 13, 50), (cx + s * 10, 62)], 1.25)
        L(hair_l, [(cx + s * 13, 22), (cx + s * 14.2, 34), (cx + s * 12.5, 48)], 0.65)

    # ---- legs & shoes
    for s in (-1, 1):
        poly(skin, [(cx + s * 2, 52), (cx + s * 6.5, 52), (cx + s * 6, 64), (cx + s * 2.8, 64)])
        poly(skin_sh, [(cx + s * 2, 52), (cx + s * 3.2, 52), (cx + s * 3.4, 64), (cx + s * 2.8, 64)])
        E((150, 40, 70), cx + s * 4.4 - 3.4, 63.5, 6.8, 3.6)

    # ---- arms
    for s in (-1, 1):
        poly(skin, [(cx + s * 7.5, 33), (cx + s * 10, 34), (cx + s * 12, 47), (cx + s * 10, 48)])
        poly(skin_sh, [(cx + s * 7.5, 33), (cx + s * 8.6, 33.5), (cx + s * 10.6, 47.5), (cx + s * 10, 48)])
        C(skin, cx + s * 11, 48.5, 1.8)

    # ---- dress: fitted bodice + flared skirt
    poly(dress, [(cx - 7.5, 32), (cx + 7.5, 32), (cx + 5.5, 42), (cx + 14, 58), (cx - 14, 58), (cx - 5.5, 42)])
    poly(dress_hi, [(cx - 7.5, 32), (cx - 3, 32), (cx - 3, 42), (cx - 9, 58), (cx - 14, 58), (cx - 5.5, 42)])
    L((255, 255, 255), [(cx - 5.5, 42.2), (cx + 5.5, 42.2)], 0.9)           # waist sash
    L(OL, [(cx - 14, 58), (cx + 14, 58)], 0.5)
    for i in range(-2, 3):                                                   # skirt folds
        L(dress_hi, [(cx + i * 1.6, 44), (cx + i * 2.8, 57)], 0.4)
    # neckline
    poly(skin, [(cx - 4.5, 32), (cx + 4.5, 32), (cx, 36.5)])

    # ---- neck
    poly(skin_sh, [(cx - 3, 27), (cx + 3, 27), (cx + 3.6, 33), (cx - 3.6, 33)])
    poly(skin, [(cx - 3, 27), (cx + 3, 27), (cx + 3, 31), (cx - 3, 31)])

    # ---- face (soft oval, delicate chin)
    E(skin, cx - 10.2, 6.5, 20.4, 22)
    poly(skin, [(cx - 8.5, 22), (cx + 8.5, 22), (cx + 3, 29.2), (cx - 3, 29.2)])
    for s in (-1, 1):
        L(skin_sh, [(cx + s * 10, 16), (cx + s * 9, 22), (cx + s * 5, 27.5)], 0.5)   # cheek contour
    E(skin_hi, cx - 2.2, 9, 4.4, 5)                                                  # forehead glow

    # ---- blush (alpha)
    bl = pygame.Surface((Wd * K, Hd * K), pygame.SRCALPHA)
    for s in (-1, 1):
        pygame.draw.ellipse(bl, (255, 110, 140, 90), ii((cx + s * 6.2 - 2.6) * K, 21.2 * K, 5.2 * K, 3.2 * K))
    surf.blit(bl, (0, 0))

    # ---- eyebrows
    for s in (-1, 1):
        L(hair_d, [(cx + s * 2.2, 14.4), (cx + s * 5.2, 13.2), (cx + s * 8, 14.2)], 0.75)

    # ---- eyes: big, bright, long lashes
    ey = 18.2
    for s in (-1, 1):
        ex = cx + s * 5.2
        L((205, 140, 125), [(ex - 3.8, ey - 3.2), (ex, ey - 4.4), (ex + 3.8, ey - 3.0)], 0.35)  # lid crease
        E((255, 255, 255), ex - 3.6, ey - 2.4, 7.2, 4.8)                                       # sclera
        C((40, 90, 140), ex, ey, 2.45)                                                         # iris edge
        C((70, 150, 205), ex, ey + 0.1, 2.0)
        C((130, 205, 235), ex, ey + 0.8, 1.2)
        C((12, 14, 28), ex, ey, 1.0)                                                           # pupil
        C((255, 255, 255), ex - 0.9, ey - 0.9, 0.7)                                            # sparkle
        C((255, 255, 255), ex + 0.9, ey + 0.9, 0.35)
        # upper lash line (thick, winged)
        top = [(ex - 3.8, ey + 0.2), (ex - 3.0, ey - 1.5), (ex - 1.2, ey - 2.5), (ex + 1.2, ey - 2.6),
               (ex + 3.0, ey - 1.6), (ex + 3.9, ey - 0.2)]
        L((18, 10, 14), top, 0.95)
        wing = (ex + s * 3.9, ey - 0.2), (ex + s * 5.4, ey - 1.7)
        L((18, 10, 14), list(wing), 0.6)
        # individual upper lashes fanning outward
        for i, (lx, ly) in enumerate([(-2.6, -2.0), (-1.2, -2.5), (0.4, -2.65), (2.0, -2.3), (3.2, -1.5)]):
            L((18, 10, 14), [(ex + lx, ey + ly), (ex + lx + s * 0.6 + (i - 2) * 0.25, ey + ly - 1.6)], 0.32)
        # lower lashes
        for lx in (-2.4, -0.8, 0.8, 2.4):
            L((70, 36, 36), [(ex + lx, ey + 2.3), (ex + lx + s * 0.2, ey + 3.0)], 0.22)
        L((225, 150, 140), [(ex - 2.8, ey + 2.5), (ex, ey + 2.7), (ex + 2.8, ey + 2.5)], 0.25)

    # ---- nose
    L(skin_sh, [(cx, 19.8), (cx - 0.7, 23.0), (cx + 0.5, 23.4)], 0.35)
    C((200, 130, 115), cx - 1.2, 23.6, 0.4)
    C((200, 130, 115), cx + 1.2, 23.6, 0.4)
    C(skin_hi, cx - 0.2, 21.2, 0.45)

    # ---- lips: full, glossy, vivid red lipstick
    lip_d, lip_m = (140, 8, 32), (210, 18, 48)
    poly(lip_d, [(cx - 4.0, 25.9), (cx - 2.0, 24.7), (cx - 0.5, 25.1), (cx, 25.4), (cx + 0.5, 25.1),
                 (cx + 2.0, 24.7), (cx + 4.0, 25.9), (cx, 26.6)])
    poly(lip_m, [(cx - 3.8, 26.0), (cx, 26.5), (cx + 3.8, 26.0), (cx + 3.0, 27.8), (cx, 28.7), (cx - 3.0, 27.8)])
    L((90, 5, 25), [(cx - 4.0, 26.0), (cx, 26.7), (cx + 4.0, 26.0)], 0.32)
    E((255, 120, 140), cx - 1.9, 26.9, 3.8, 1.0)
    C((255, 200, 210), cx - 0.5, 25.4, 0.4)
    C((255, 230, 235), cx + 0.8, 27.3, 0.35)

    # ---- hair top: side-swept bangs, volume and shine
    poly(hair_d, [(cx - 11.2, 17), (cx - 11, 8), (cx - 6, 3.2), (cx + 2, 2.2), (cx + 9, 4.5), (cx + 11.4, 10), (cx + 11, 17),
                  (cx + 9.2, 11), (cx + 4, 8), (cx - 1, 7.6), (cx - 6, 9.5), (cx - 9, 13)])
    poly(hair_m, [(cx - 10, 9), (cx - 5, 4.4), (cx + 2, 3.4), (cx + 8, 5.4), (cx + 3, 6.2), (cx - 4, 7.4), (cx - 8, 11)])
    L(hair_l, [(cx - 8, 7.4), (cx - 3, 4.8), (cx + 3, 4.4), (cx + 7.5, 6.0)], 0.9)        # glossy highlight
    L(hair_l, [(cx - 3.5, 8.6), (cx - 0.5, 7.2), (cx + 4, 8.0)], 0.4)
    for s in (-1, 1):
        L(hair_m, [(cx + s * 10.6, 10), (cx + s * 11.6, 18), (cx + s * 11.8, 26)], 0.7)   # face-framing locks
        L(hair_l, [(cx + s * 10.9, 14), (cx + s * 11.5, 20)], 0.35)
    # tiny hair bow
    poly((255, 90, 140), [(cx + 8, 6), (cx + 13, 3), (cx + 13, 9)])
    poly((255, 90, 140), [(cx + 8, 6), (cx + 3.5, 3.2), (cx + 3.5, 8.8)])
    C((255, 170, 200), cx + 8, 6, 1.0)

    return pygame.transform.smoothscale(surf, (Wd, Hd))

def girl_sprite(rescued):
    k = "safe" if rescued else "help"
    if k not in GIRL_SPR:
        GIRL_SPR[k] = make_girl((100, 200, 130), (140, 230, 165)) if rescued else make_girl((214, 60, 110), (245, 110, 150))
    return GIRL_SPR[k]


