def para_girl_sprite(face=1):
    """Return cached para girl sprite, flipped by facing direction."""
    if "base" not in PARA_GIRL_SPR:
        base = make_para_girl()
        PARA_GIRL_SPR["base"] = base
        PARA_GIRL_SPR["flip"] = pygame.transform.flip(base, True, False)
    return PARA_GIRL_SPR["base"] if face >= 0 else PARA_GIRL_SPR["flip"]

