YOR_SPR_CACHE = {}

def gf_dress_rect(i):
    return pygame.Rect(30 + (i % 10) * 122, 100 + (i // 10) * 118, 114, 110)

def make_yor_girl(dress_idx=0):
    """Yor Forger inspired look: long black hair, red eyes, elegant face, selected dress."""
    d = GF_DRESSES[dress_idx % len(GF_DRESSES)]
    K = 6
    Wd, Hd = 50, 80
    surf = pygame.Surface((Wd * K, Hd * K), pygame.SRCALPHA)
    cx = 25
    skin, skin_sh, skin_hi = (250, 210, 190), (230, 165, 140), (255, 230, 215)
    hair_d, hair_m, hair_l = (12, 10, 14), (28, 24, 32), (70, 65, 80)
    dress, dress_hi, dress_d = d["dress"], d["dress_hi"], d["dress_d"]
    accent = d["accent"]
    style = d["style"]

    def P(pts):
        return [(x * K, y * K) for x, y in pts]
    def poly(col, pts):
        pygame.draw.polygon(surf, col, P(pts))
    def E(col, x, y, w, h):
        pygame.draw.ellipse(surf, col, ii(x * K, y * K, w * K, h * K))
    def C(col, x, y, r):
        pygame.draw.circle(surf, col, ii(x * K, y * K), max(1, int(r * K)))
    def L(col, pts, w):
        pygame.draw.lines(surf, col, False, P(pts), max(1, int(w * K)))

    # ---- very long black hair (Yor style, past hips)
    E(hair_d, cx - 16, 0.5, 32, 36)
    for s in (-1, 1):
        poly(hair_d, [(cx + s * 13, 12), (cx + s * 17, 28), (cx + s * 16.5, 50),
                      (cx + s * 14, 66), (cx + s * 10, 72), (cx + s * 8, 55),
                      (cx + s * 8.5, 40), (cx + s * 10, 24)])
        L(hair_m, [(cx + s * 14, 16), (cx + s * 16, 34), (cx + s * 15, 54), (cx + s * 12, 68)], 1.4)
        L(hair_l, [(cx + s * 14.5, 20), (cx + s * 16, 36)], 0.6)
        # subtle red undertone tips
        L((90, 25, 35), [(cx + s * 13, 62), (cx + s * 11, 70)], 0.9)

    # ---- legs / shoes depending on style
    if style == 5:  # spicy short
        for s in (-1, 1):
            poly(skin, [(cx + s * 2.2, 52), (cx + s * 6.8, 52), (cx + s * 6.4, 68), (cx + s * 2.8, 68)])
            poly(skin_sh, [(cx + s * 2.2, 52), (cx + s * 3.8, 52), (cx + s * 4.0, 68), (cx + s * 2.8, 68)])
            E((20, 15, 18), cx + s * 4.5 - 3.5, 67.0, 7.2, 3.5)
    elif style == 3:  # mermaid
        poly(dress, [(cx - 7, 50), (cx + 7, 50), (cx + 10, 72), (cx - 10, 72)])
        poly(dress_hi, [(cx - 7, 50), (cx - 1, 50), (cx - 2, 72), (cx - 10, 72)])
        E(dress_d, cx - 11, 68, 22, 6)
    else:
        for s in (-1, 1):
            poly(skin, [(cx + s * 2.0, 58), (cx + s * 6.5, 58), (cx + s * 6.2, 70), (cx + s * 2.6, 70)])
            E((25, 18, 22), cx + s * 4.3 - 3.3, 69.0, 6.8, 3.4)

    # ---- arms
    for s in (-1, 1):
        poly(skin, [(cx + s * 8, 34), (cx + s * 10.5, 35), (cx + s * 12.5, 50), (cx + s * 10.5, 51)])
        poly(skin_sh, [(cx + s * 8, 34), (cx + s * 9, 34.5), (cx + s * 11, 50.5), (cx + s * 10.5, 51)])
        C(skin, cx + s * 11.5, 51.5, 1.9)

    # ---- dress body by style
    if style == 5:  # spicy short / mini
        poly(dress, [(cx - 8, 32), (cx + 8, 32), (cx + 9, 52), (cx - 9, 52)])
        poly(dress_hi, [(cx - 8, 32), (cx - 2, 32), (cx - 2, 52), (cx - 9, 52)])
        L(accent, [(cx - 8, 51.5), (cx + 8, 51.5)], 0.7)
    elif style == 2:  # off-shoulder
        poly(dress, [(cx - 9, 36), (cx + 9, 36), (cx + 10, 58), (cx + 12, 70), (cx - 12, 70), (cx - 10, 58)])
        poly(dress_hi, [(cx - 9, 36), (cx - 2, 36), (cx - 3, 58), (cx - 8, 70), (cx - 12, 70), (cx - 10, 58)])
        L(skin, [(cx - 9, 34), (cx + 9, 34)], 1.2)
        poly(skin, [(cx - 5, 32), (cx + 5, 32), (cx + 4, 37), (cx - 4, 37)])
    elif style == 4:  # ballgown
        poly(dress, [(cx - 8, 33), (cx + 8, 33), (cx + 7, 48), (cx + 16, 72), (cx - 16, 72), (cx - 7, 48)])
        poly(dress_hi, [(cx - 8, 33), (cx - 2, 33), (cx - 2, 48), (cx - 10, 72), (cx - 16, 72), (cx - 7, 48)])
        for i in range(-3, 4):
            L(dress_hi, [(cx + i * 2, 50), (cx + i * 3.5, 71)], 0.35)
    elif style == 1:  # slit elegant
        poly(dress, [(cx - 8, 33), (cx + 8, 33), (cx + 7.5, 55), (cx + 9, 70), (cx + 2, 70), (cx + 3, 55),
                     (cx - 3, 55), (cx - 4, 70), (cx - 9, 70), (cx - 7.5, 55)])
        poly(dress_hi, [(cx - 8, 33), (cx - 2, 33), (cx - 2, 55), (cx - 4, 70), (cx - 9, 70), (cx - 7.5, 55)])
        L(accent, [(cx + 2.5, 56), (cx + 3.5, 69)], 0.5)
    else:  # classic long
        poly(dress, [(cx - 8, 33), (cx + 8, 33), (cx + 7, 50), (cx + 11, 70), (cx - 11, 70), (cx - 7, 50)])
        poly(dress_hi, [(cx - 8, 33), (cx - 2, 33), (cx - 2, 50), (cx - 7, 70), (cx - 11, 70), (cx - 7, 50)])
        L(accent, [(cx - 6, 42), (cx + 6, 42)], 0.6)

    # neckline
    poly(skin, [(cx - 4.2, 33), (cx + 4.2, 33), (cx, 37.5)])
    # waist accent ribbon
    L(accent, [(cx - 7, 44), (cx + 7, 44)], 0.9)
    C(accent, cx, 44, 1.3)

    # ---- neck
    poly(skin_sh, [(cx - 3, 28), (cx + 3, 28), (cx + 3.5, 34), (cx - 3.5, 34)])
    poly(skin, [(cx - 3, 28), (cx + 3, 28), (cx + 3, 32.5), (cx - 3, 32.5)])

    # ---- face (elegant Yor-like oval)
    E(skin, cx - 10.5, 6.5, 21, 23)
    poly(skin, [(cx - 8.5, 23), (cx + 8.5, 23), (cx + 3, 30.2), (cx - 3, 30.2)])
    for s in (-1, 1):
        L(skin_sh, [(cx + s * 10, 16), (cx + s * 9, 22.5), (cx + s * 5, 28)], 0.5)
    E(skin_hi, cx - 2.2, 9, 4.5, 5)

    # soft blush
    bl = pygame.Surface((Wd * K, Hd * K), pygame.SRCALPHA)
    for s in (-1, 1):
        pygame.draw.ellipse(bl, (255, 100, 130, 100), ii((cx + s * 6.4 - 2.7) * K, 21.5 * K, 5.4 * K, 3.2 * K))
    surf.blit(bl, (0, 0))

    # eyebrows (thin elegant)
    for s in (-1, 1):
        L((20, 16, 18), [(cx + s * 2.3, 14.2), (cx + s * 5.3, 13.0), (cx + s * 8.2, 14.0)], 0.7)

    # ---- eyes: distinctive red Yor eyes
    ey = 18.3
    for s in (-1, 1):
        ex = cx + s * 5.3
        L((200, 130, 120), [(ex - 3.8, ey - 3.2), (ex, ey - 4.4), (ex + 3.8, ey - 3.0)], 0.35)
        E((255, 255, 255), ex - 3.7, ey - 2.5, 7.4, 5.0)
        C((160, 25, 40), ex, ey, 2.5)          # red iris
        C((200, 40, 55), ex, ey + 0.15, 1.9)
        C((255, 90, 100), ex, ey + 0.7, 1.1)
        C((20, 8, 12), ex, ey, 1.0)
        C((255, 255, 255), ex - 0.9, ey - 0.9, 0.7)
        C((255, 255, 255), ex + 0.9, ey + 0.85, 0.35)
        top = [(ex - 3.8, ey + 0.15), (ex - 3.0, ey - 1.5), (ex - 1.2, ey - 2.55),
               (ex + 1.2, ey - 2.65), (ex + 3.0, ey - 1.55), (ex + 3.9, ey - 0.15)]
        L((15, 8, 12), top, 1.0)
        wing = (ex + s * 3.9, ey - 0.15), (ex + s * 5.5, ey - 1.7)
        L((15, 8, 12), list(wing), 0.6)
        for i, (lx, ly) in enumerate([(-2.6, -2.0), (-1.2, -2.55), (0.4, -2.7), (2.0, -2.35), (3.2, -1.5)]):
            L((15, 8, 12), [(ex + lx, ey + ly), (ex + lx + s * 0.6 + (i - 2) * 0.25, ey + ly - 1.65)], 0.32)

    # nose
    L(skin_sh, [(cx, 20.0), (cx - 0.7, 23.3), (cx + 0.5, 23.7)], 0.35)
    C((200, 130, 115), cx - 1.2, 23.9, 0.4)
    C((200, 130, 115), cx + 1.2, 23.9, 0.4)

    # ---- vivid red lips
    lip_d, lip_m = (140, 8, 28), (200, 15, 42)
    poly(lip_d, [(cx - 3.9, 26.2), (cx - 1.9, 24.9), (cx - 0.5, 25.3), (cx, 25.6),
                 (cx + 0.5, 25.3), (cx + 1.9, 24.9), (cx + 3.9, 26.2), (cx, 26.9)])
    poly(lip_m, [(cx - 3.7, 26.3), (cx, 26.8), (cx + 3.7, 26.3), (cx + 2.9, 28.0), (cx, 28.9), (cx - 2.9, 28.0)])
    L((90, 5, 22), [(cx - 3.9, 26.3), (cx, 27.0), (cx + 3.9, 26.3)], 0.3)
    E((255, 110, 130), cx - 1.8, 27.2, 3.6, 0.95)
    C((255, 200, 210), cx - 0.5, 25.6, 0.38)

    # ---- hair top / bangs (Yor signature)
    poly(hair_d, [(cx - 12, 17), (cx - 11.5, 7), (cx - 6, 2.5), (cx + 1, 1.5), (cx + 9, 3.5),
                  (cx + 12, 9), (cx + 11.5, 17), (cx + 9, 10), (cx + 3, 7), (cx - 2, 6.5),
                  (cx - 7, 8.5), (cx - 10, 12)])
    poly(hair_m, [(cx - 10, 8.5), (cx - 5, 3.8), (cx + 1, 2.8), (cx + 7.5, 4.5), (cx + 2, 5.5), (cx - 4, 6.8)])
    L(hair_l, [(cx - 8, 7), (cx - 3, 4.2), (cx + 2.5, 3.8), (cx + 7, 5.2)], 0.85)
    # side face-framing locks
    for s in (-1, 1):
        L(hair_m, [(cx + s * 11.5, 10), (cx + s * 12.8, 22), (cx + s * 13, 36)], 0.8)
        L(hair_l, [(cx + s * 11.8, 14), (cx + s * 12.5, 24)], 0.4)
    # small rose hair accent
    C(accent, cx + 8.5, 6.0, 1.4)
    C((255, 180, 190), cx + 8.5, 5.7, 0.6)

    return pygame.transform.smoothscale(surf, (Wd, Hd))

def yor_girl_sprite(face=1, dress_idx=0):
    key = (dress_idx, face >= 0)
    if key not in YOR_SPR_CACHE:
        base = make_yor_girl(dress_idx)
        YOR_SPR_CACHE[(dress_idx, True)] = base
        YOR_SPR_CACHE[(dress_idx, False)] = pygame.transform.flip(base, True, False)
    return YOR_SPR_CACHE[(dress_idx, face >= 0)]


def make_bg():
    bg = pygame.Surface((W, H))
    top, mid, bot = (62, 50, 112), (112, 78, 146), (236, 128, 66)
    for y in range(H):
        t = y / H
        c = [lerp(top[i], mid[i], t / 0.6) if t < 0.6 else lerp(mid[i], bot[i], (t - 0.6) / 0.4) for i in range(3)]
        pygame.draw.line(bg, ii(*c), (0, y), (W, y))
    layers = []
    L = W * 2
    for k, (base, amp, col, f) in enumerate([(430, 90, (84, 66, 128), 0.15), (500, 80, (66, 50, 108), 0.3),
                                              (570, 60, (48, 36, 84), 0.5)]):
        ls = pygame.Surface((L, H), pygame.SRCALPHA)
        ph1, ph2 = random.uniform(0, 6), random.uniform(0, 6)
        pts = [(0, H)]
        for x in range(0, L + 1, 20):
            h = base - amp * (0.55 * math.sin(2 * math.pi * 3 * x / L + ph1) +
                              0.45 * abs(math.sin(2 * math.pi * 5 * x / L + ph2)))
            pts.append((x, h))
        pts.append((L, H))
        pygame.draw.polygon(ls, col, pts)
        layers.append((ls, f))
    return bg, layers

ALLIED_JET_CACHE = {}

def allied_fighter_sprite(flip=False):
    """Advanced 5th-gen stealth fighter (side view, nose right): swept canted tails,
    chined fuselage, bubble canopy, intake, IAF roundel, under-wing missiles."""
    key = bool(flip)
    if key in ALLIED_JET_CACHE:
        return ALLIED_JET_CACHE[key]
    S = 3
    Wd, Hd = 230, 90
    big = pygame.Surface((Wd * S, Hd * S), pygame.SRCALPHA)
    def P(pts): return [(int(x * S), int(y * S)) for x, y in pts]
    def poly(c, pts, edge=None, w=1):
        pygame.draw.polygon(big, c, P(pts))
        if edge: pygame.draw.polygon(big, edge, P(pts), max(1, w * S // 2))
    ol = (14, 20, 30)
    # far-side tail fin and stabiliser (darker, behind the body)
    poly((52, 62, 78), [(52, 38), (44, 12), (66, 12), (82, 36)], ol)
    poly((46, 56, 72), [(34, 46), (14, 58), (40, 58), (62, 47)], ol)
    # missiles under the wing (white body, red nose, fins)
    for mx in (92, 112):
        poly((225, 228, 235), [(mx, 66), (mx + 26, 66), (mx + 32, 68), (mx + 26, 70), (mx, 70)], ol)
        poly((220, 50, 45), [(mx + 26, 66), (mx + 32, 68), (mx + 26, 70)])
        poly((90, 100, 120), [(mx, 66), (mx - 4, 63), (mx + 4, 66)])
        poly((90, 100, 120), [(mx, 70), (mx - 4, 73), (mx + 4, 70)])
    # main wing (delta, swept)
    poly((86, 98, 122), [(78, 46), (52, 70), (112, 70), (150, 49)], ol, 2)
    poly((120, 134, 160), [(84, 47), (66, 63), (108, 63), (136, 49)])
    # fuselage
    fus = [(14, 40), (30, 33), (70, 30), (118, 32), (160, 37), (206, 44), (160, 48), (118, 51), (70, 51), (28, 47)]
    poly((105, 120, 146), fus, ol, 2)
    # upper highlight / lower shade for volume
    poly((150, 168, 194), [(30, 34), (70, 31), (118, 33), (160, 38), (206, 44), (150, 40), (100, 37), (50, 37)])
    poly((70, 82, 104), [(28, 46), (70, 50), (118, 50), (160, 47), (206, 44), (150, 45), (100, 46), (50, 44)])
    # chine edge line and panel lines
    pygame.draw.line(big, (190, 205, 225), (40 * S, 40 * S), (190 * S, 44 * S), S)
    for px in (60, 88, 150):
        pygame.draw.line(big, (60, 72, 94), (px * S, 33 * S), (px * S + 2 * S, 49 * S), max(1, S // 2))
    # air intake
    poly((14, 18, 26), [(110, 40), (132, 41), (136, 50), (112, 51)], ol)
    poly((40, 48, 62), [(114, 42), (130, 43), (132, 48), (115, 49)])
    # radome tip and pitot
    poly((52, 58, 72), [(184, 42), (206, 44), (186, 46)])
    pygame.draw.line(big, (230, 230, 240), (206 * S, 44 * S), (219 * S, 44 * S), S)
    # canopy
    poly((18, 40, 70), [(128, 33), (140, 24), (160, 26), (176, 37), (132, 37)], ol, 2)
    poly((80, 175, 235), [(133, 33), (142, 27), (158, 28), (170, 36), (136, 36)])
    poly((200, 240, 255), [(144, 28), (156, 29), (150, 33), (142, 33)])
    # near-side canted tail fin and stabiliser
    poly((92, 106, 134), [(58, 38), (46, 6), (72, 6), (94, 36)], ol, 2)
    poly((190, 40, 50), [(52, 20), (48, 10), (62, 10), (70, 22)])
    poly((235, 235, 240), [(56, 28), (52, 21), (71, 22), (77, 29)])
    poly((92, 106, 134), [(30, 44), (6, 60), (40, 60), (66, 47)], ol, 2)
    # twin nozzles
    poly((30, 32, 40), [(10, 36), (22, 34), (24, 46), (10, 44)], ol)
    poly((70, 74, 88), [(10, 37), (17, 36), (17, 44), (10, 43)])
    # IAF roundel (saffron / white / green) on the tail boom
    cx, cy = 86 * S, 41 * S
    pygame.draw.circle(big, (30, 140, 60), (cx, cy), 6 * S)
    pygame.draw.circle(big, (245, 245, 245), (cx, cy), int(4.2 * S))
    pygame.draw.circle(big, (255, 140, 30), (cx, cy), int(2.2 * S))
    # cyan identification stripe
    pygame.draw.line(big, (80, 220, 255), (150 * S, 41 * S), (176 * S, 43 * S), 2 * S)
    spr = pygame.transform.smoothscale(big, (int(Wd * 0.62), int(Hd * 0.62)))
    if flip:
        spr = pygame.transform.flip(spr, True, False)
    ALLIED_JET_CACHE[key] = spr
    return spr


RIOT_SHIELD_BASE = {}
RIOT_SHIELD_CACHE = {}

def riot_shield_sprite(height=88):
    """Front view of the police riot shield: charcoal convex body, bevelled rim, top grip
    strip, oval viewport with a reflective glass streak and screws, two clamp handles
    and the white 'POLICE' lettering."""
    if height in RIOT_SHIELD_CACHE:
        return RIOT_SHIELD_CACHE[height]
    if "big" not in RIOT_SHIELD_BASE:
        S = 4
        Wd, Hd = 130, 220
        body = pygame.Surface((Wd * S, Hd * S), pygame.SRCALPHA)
        def R(x, y, w, h): return pygame.Rect(int(x * S), int(y * S), int(w * S), int(h * S))
        def rr(surf, col, rect, rad, width=0):
            pygame.draw.rect(surf, col, rect, width, border_radius=int(rad * S))
        rr(body, (22, 20, 18), R(2, 0, 126, 220), 30)                 # outer edge
        rr(body, (48, 44, 40), R(5, 3, 120, 214), 27)                 # main face
        rr(body, (92, 84, 74), R(8, 6, 114, 208), 24, 2 * S)          # bevel highlight
        rr(body, (34, 31, 28), R(11, 9, 108, 202), 22, S)             # inner groove
        # convex shading: darker toward the left/right edges, slightly lighter centre
        grad = pygame.Surface(body.get_size(), pygame.SRCALPHA)
        for x in range(body.get_width()):
            t = abs(x / S - 65) / 65.0
            v = int(255 - 105 * t ** 2.2)
            pygame.draw.line(grad, (v, v, v, 255), (x, 0), (x, body.get_height()))
        body.blit(grad, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        # top grip strip
        rr(body, (24, 22, 20), R(24, 13, 82, 13), 6)
        rr(body, (66, 60, 52), R(24, 13, 82, 13), 6, S)
        # viewport: frame, glass, reflection, screws
        rr(body, (16, 15, 14), R(18, 36, 94, 46), 22)
        rr(body, (84, 78, 70), R(18, 36, 94, 46), 22, S)
        glass = pygame.Surface((80 * S, 32 * S), pygame.SRCALPHA)
        rr(glass, (86, 94, 102), glass.get_rect(), 14)
        for i in range(glass.get_height()):
            f = i / glass.get_height()
            pygame.draw.line(glass, (int(70 + 70 * (1 - f)), int(78 + 70 * (1 - f)), int(86 + 66 * (1 - f)), 255),
                             (6 * S, i), (glass.get_width() - 6 * S, i))
        pygame.draw.polygon(glass, (235, 238, 240, 235), [(34 * S, 0), (52 * S, 0), (38 * S, 32 * S), (22 * S, 32 * S)])
        pygame.draw.polygon(glass, (40, 44, 50, 200), [(58 * S, 0), (74 * S, 0), (66 * S, 32 * S), (54 * S, 32 * S)])
        gm = pygame.Surface(glass.get_size(), pygame.SRCALPHA)
        rr(gm, (255, 255, 255, 255), gm.get_rect(), 14)
        glass.blit(gm, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
        body.blit(glass, (25 * S, 43 * S))
        for sx_, sy_ in ((27, 45), (103, 45), (27, 73), (103, 73), (65, 40), (65, 78)):
            pygame.draw.circle(body, (110, 104, 94), (sx_ * S, sy_ * S), int(1.7 * S))
        # clamp handles
        for cx_ in (22, 90):
            rr(body, (20, 18, 16), R(cx_, 108, 20, 36), 3)
            rr(body, (88, 80, 70), R(cx_, 108, 20, 36), 3, S)
            rr(body, (8, 8, 8), R(cx_ + 6, 114, 8, 22), 2)
            pygame.draw.line(body, (130, 122, 108), (int((cx_ + 2) * S), int(110 * S)), (int((cx_ + 18) * S), int(110 * S)), S)
        # POLICE lettering
        try:
            fnt = _font(96, True, "arialblack,arial,helvetica")
            tx = fnt.render("POLICE", True, (214, 208, 196))
            sh = fnt.render("POLICE", True, (14, 13, 12))
            tw = 100 * S
            th = int(tx.get_height() * tw / tx.get_width())
            tx = pygame.transform.smoothscale(tx, (tw, th))
            sh = pygame.transform.smoothscale(sh, (tw, th))
            tr = tx.get_rect(center=(65 * S, 158 * S))
            body.blit(sh, tr.move(S, S))
            body.blit(tx, tr)
        except Exception:
            pass
        # weathering: scratches and a darker, dirtier lower edge
        rng = random.Random(77)
        for _ in range(26):
            x0 = rng.randint(14, 116); y0 = rng.randint(30, 205)
            pygame.draw.line(body, (96, 90, 80, 120), (x0 * S, y0 * S),
                             ((x0 + rng.randint(-8, 8)) * S, (y0 + rng.randint(2, 9)) * S), 1)
        dirt = pygame.Surface(body.get_size(), pygame.SRCALPHA)
        for y in range(180 * S, 220 * S):
            a = int(255 - 70 * (y - 180 * S) / (40 * S))
            pygame.draw.line(dirt, (a, a, a, 255), (0, y), (body.get_width(), y))
        for y in range(0, 180 * S):
            pygame.draw.line(dirt, (255, 255, 255, 255), (0, y), (body.get_width(), y))
        body.blit(dirt, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        RIOT_SHIELD_BASE["big"] = body
    big = RIOT_SHIELD_BASE["big"]
    w = max(8, int(height * 130 / 220.0))
    spr = pygame.transform.smoothscale(big, (w, int(height)))
    RIOT_SHIELD_CACHE[height] = spr
    return spr


def starburst(surf, x, y, r, c1, c2, n=8, rot=0.0, inner=0.5):
    pts = []
    for i in range(n * 2):
        a = rot + i * math.pi / n
        rr_ = r if i % 2 == 0 else r * inner
        pts.append((x + math.cos(a) * rr_, y + math.sin(a) * rr_))
    pygame.draw.polygon(surf, c1, pts)
    pygame.draw.polygon(surf, c2, [(x + (px - x) * 0.55, y + (py - y) * 0.55) for px, py in pts])

def draw_flame(surf, x, y):
    for _ in range(2):
        pygame.draw.circle(surf, (230, 230, 235), (int(x + random.uniform(-6, 6)), int(y + random.uniform(16, 30))),
                           random.randint(4, 8))
    starburst(surf, x, y + 8, random.randint(14, 20), (255, 90, 30), (255, 220, 90), 7, random.uniform(0, 6.28), 0.45)

def rot_pts(pts, ang, ox, oy):
    c, s = math.cos(ang), math.sin(ang)
    return [(ox + px * c - py * s, oy + px * s + py * c) for px, py in pts]

def norm_ang(a):
    while a > math.pi:
        a -= 2 * math.pi
    while a < -math.pi:
        a += 2 * math.pi
    return a

# --------------------------------------------------------------- entities

# =====================================================================================
#  GRAPHICS ENGINE LAYER  (PyOpenGL post-FX  +  PyBullet shards  +  raylib 3D backdrop)
#  Every piece is optional: if a library or GPU feature is missing, the game falls back.
#  F5 = toggle post-FX   F6 = toggle 3D titan backdrop   F7 = toggle bullet shards
# =====================================================================================
FX = {"post": True, "backdrop": True, "shards": True, "photo": True}

_VERT = """
#version 120
varying vec2 uv;
void main(){ gl_Position = ftransform(); uv = gl_MultiTexCoord0.xy; }
"""
_FRAG = """
#version 120
varying vec2 uv;
uniform sampler2D tex;
uniform float time;
uniform float shake;
uniform vec2 sun;
uniform vec2 texel;

vec3 sample_ca(vec2 p, float k){
    vec2 d = (p - 0.5) * k;
    return vec3(texture2D(tex, p + d).r, texture2D(tex, p).g, texture2D(tex, p - d).b);
}
float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233)) + time) * 43758.5453); }
vec3 aces(vec3 x){ return clamp((x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14), 0.0, 1.0); }

void main(){
    float ca = 0.0006 + shake * 0.0002;
    vec3 col = sample_ca(uv, ca);

    // bloom: two rings of bright-pass taps
    vec3 bloom = vec3(0.0);
    for(int i = 0; i < 16; i++){
        float a = float(i) * 0.3926991;
        vec2 dir = vec2(cos(a), sin(a));
        vec3 s1 = texture2D(tex, uv + dir * texel * 6.0).rgb;
        vec3 s2 = texture2D(tex, uv + dir * texel * 16.0).rgb;
        bloom += max(s1 - 0.82, 0.0) * 0.6 + max(s2 - 0.8, 0.0) * 0.4;
    }
    bloom /= 16.0;
    col += bloom * 0.45;

    // god-rays toward the sun position
    vec2 delta = (uv - sun) / 18.0;
    vec2 p = uv;
    float ray = 0.0; float decay = 1.0;
    for(int i = 0; i < 18; i++){
        p -= delta;
        vec3 s = texture2D(tex, p).rgb;
        float l = max(dot(s, vec3(0.33)) - 0.85, 0.0);
        ray += l * decay; decay *= 0.93;
    }
    col += vec3(1.0, 0.85, 0.65) * ray * 0.012;

    // filmic tone-map + cinematic teal/orange grade
    col = mix(col, aces(col), 0.5);
    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    col = mix(col * vec3(0.97, 1.0, 1.03), col * vec3(1.03, 1.0, 0.96), smoothstep(0.25, 0.8, lum));
    col = mix(vec3(lum), col, 1.04);

    // vignette + grain
    vec2 q = uv - 0.5;
    col *= 1.0 - dot(q, q) * 0.6;
    col += (hash(uv * 900.0) - 0.5) * 0.008;
    gl_FragColor = vec4(col, 1.0);
}
"""

class GLPost:
    """Uploads the pygame frame as a texture and runs the post-process shader."""
    def __init__(self):
        self.ok = False
        self.tex = None
        self.prog = None
        if not PYOPENGL_AVAILABLE:
            return
        try:
            self.prog = gl_shaders.compileProgram(
                gl_shaders.compileShader(_VERT, gl.GL_VERTEX_SHADER),
                gl_shaders.compileShader(_FRAG, gl.GL_FRAGMENT_SHADER))
            self.tex = gl.glGenTextures(1)
            gl.glBindTexture(gl.GL_TEXTURE_2D, self.tex)
            gl.glTexParameteri(gl.GL_TEXTURE_2D, gl.GL_TEXTURE_MIN_FILTER, gl.GL_LINEAR)
            gl.glTexParameteri(gl.GL_TEXTURE_2D, gl.GL_TEXTURE_MAG_FILTER, gl.GL_LINEAR)
            gl.glTexParameteri(gl.GL_TEXTURE_2D, gl.GL_TEXTURE_WRAP_S, gl.GL_CLAMP_TO_EDGE)
            gl.glTexParameteri(gl.GL_TEXTURE_2D, gl.GL_TEXTURE_WRAP_T, gl.GL_CLAMP_TO_EDGE)
            gl.glPixelStorei(gl.GL_UNPACK_ALIGNMENT, 1)
            gl.glTexImage2D(gl.GL_TEXTURE_2D, 0, gl.GL_RGB, W, H, 0, gl.GL_RGB, gl.GL_UNSIGNED_BYTE, None)
            self.u = {n: gl.glGetUniformLocation(self.prog, n) for n in ("tex", "time", "shake", "sun", "texel")}
            self._tobytes = getattr(pygame.image, "tobytes", None) or pygame.image.tostring
            self.ok = True
        except Exception as exc:
            print("PyOpenGL post-FX disabled:", exc)
            self.ok = False

    def present(self, surf, t, shake, sun):
        data = self._tobytes(surf, "RGB", True)      # flipped: GL origin is bottom-left
        ww, wh = pygame.display.get_window_size()
        gl.glViewport(0, 0, ww, wh)
        gl.glClear(gl.GL_COLOR_BUFFER_BIT)
        gl.glActiveTexture(gl.GL_TEXTURE0)
        gl.glBindTexture(gl.GL_TEXTURE_2D, self.tex)
        gl.glTexSubImage2D(gl.GL_TEXTURE_2D, 0, 0, 0, W, H, gl.GL_RGB, gl.GL_UNSIGNED_BYTE, data)
        gl.glUseProgram(self.prog)
        gl.glUniform1i(self.u["tex"], 0)
        gl.glUniform1f(self.u["time"], float(t % 100.0))
        gl.glUniform1f(self.u["shake"], float(min(shake, 18)))
        gl.glUniform2f(self.u["sun"], sun[0], sun[1])
        gl.glUniform2f(self.u["texel"], 1.0 / W, 1.0 / H)
        gl.glEnable(gl.GL_TEXTURE_2D)
        gl.glBegin(gl.GL_QUADS)
        for (u, v, x, y) in ((0, 0, -1, -1), (1, 0, 1, -1), (1, 1, 1, 1), (0, 1, -1, 1)):
            gl.glTexCoord2f(u, v)
            gl.glVertex2f(x, y)
        gl.glEnd()
        gl.glUseProgram(0)

    def plain(self, surf):
        """Post-FX off: blit the frame straight through without the shader."""
        data = self._tobytes(surf, "RGB", True)
        ww, wh = pygame.display.get_window_size()
        gl.glViewport(0, 0, ww, wh)
        gl.glBindTexture(gl.GL_TEXTURE_2D, self.tex)
        gl.glTexSubImage2D(gl.GL_TEXTURE_2D, 0, 0, 0, W, H, gl.GL_RGB, gl.GL_UNSIGNED_BYTE, data)
        gl.glUseProgram(0)
        gl.glEnable(gl.GL_TEXTURE_2D)
        gl.glColor3f(1, 1, 1)
        gl.glBegin(gl.GL_QUADS)
        for (u, v, x, y) in ((0, 0, -1, -1), (1, 0, 1, -1), (1, 1, 1, 1), (0, 1, -1, 1)):
            gl.glTexCoord2f(u, v)
            gl.glVertex2f(x, y)
        gl.glEnd()


def present_frame(game=None):
    """Replaces pygame.display.flip(): runs the OpenGL pass when available."""
    global GL_POST
    if not PYOPENGL_AVAILABLE:
        pygame.display.flip()
        return
    if GL_POST is None:
        GL_POST = GLPost()
        if not GL_POST.ok:
            # shader/context failed -> rebuild a normal window so the game stays playable
            globals()["PYOPENGL_AVAILABLE"] = False
            globals()["screen"] = pygame.display.set_mode((W, H) if WEB else (W, H), 0 if WEB else pygame.FULLSCREEN)
            return
    try:
        t = pygame.time.get_ticks() / 1000.0
        shake = getattr(game, "shake", 0) if game else 0
        sun = (0.78, 0.82)
        if FX["post"]:
            GL_POST.present(screen, t, shake, sun)
        else:
            GL_POST.plain(screen)
    except Exception as exc:
        print("PyOpenGL present failed:", exc)
    pygame.display.flip()


# ---------------------------------------------------------------- PyBullet shard world
class BulletDebris:
    """Real 3D rigid bodies (PyBullet DIRECT mode) locked to the 2D play-plane.
    World mapping: game (x, y) px  ->  bullet (x*S, 0, -y*S) metres, +Z up."""
    S = 0.01
    MAX = 110

    def __init__(self):
        self.ok = False
        self.bodies = []
        self.statics = []
        self.sig = None
        self.cid = None
        if not PYBULLET_AVAILABLE:
            return
        try:
            self.cid = pybullet.connect(pybullet.DIRECT)
            pybullet.setGravity(0, 0, -10.5, physicsClientId=self.cid)
            pybullet.setTimeStep(1.0 / FPS, physicsClientId=self.cid)
            self.ok = True
        except Exception as exc:
            print("PyBullet disabled:", exc)

    def _box(self, hx, hy, hz):
        return pybullet.createCollisionShape(pybullet.GEOM_BOX, halfExtents=[hx, hy, hz], physicsClientId=self.cid)

    def sync_world(self, platforms):
        sig = tuple((r.x, r.y, r.w, r.h) for r in platforms)
        if sig == self.sig:
            return
        self.sig = sig
        for b in self.statics:
            pybullet.removeBody(b, physicsClientId=self.cid)
        self.statics = []
        for i, r in enumerate(platforms):
            thick = max(r.h, 14) if i else 400
            top = r.top
            cx, cy = r.centerx, top + thick / 2
            shape = self._box(r.w / 2 * self.S, 0.4, thick / 2 * self.S)
            body = pybullet.createMultiBody(0, shape, basePosition=[cx * self.S, 0, -cy * self.S], physicsClientId=self.cid)
            pybullet.changeDynamics(body, -1, restitution=0.3, lateralFriction=0.8, physicsClientId=self.cid)
            self.statics.append(body)

    def clear(self):
        for sh in self.bodies:
            pybullet.removeBody(sh["id"], physicsClientId=self.cid)
        self.bodies = []

    def burst(self, x, y, n, speed=520, kind="rock"):
        if not self.ok:
            return
        pal = {"rock": [(96, 98, 104), (70, 72, 78), (120, 118, 112)],
               "metal": [(130, 145, 160), (95, 108, 122), (190, 200, 210)],
               "ember": [(255, 150, 40), (255, 90, 30), (60, 40, 35)]}[kind]
        for _ in range(n):
            if len(self.bodies) >= self.MAX:
                break
            w, h = random.uniform(5, 15), random.uniform(4, 11)
            try:
                shape = self._box(w / 2 * self.S, 0.05, h / 2 * self.S)
                a = random.uniform(-math.pi, 0)          # upward fan
                sp = random.uniform(0.3, 1.0) * speed
                bid = pybullet.createMultiBody(
                    baseMass=w * h * 0.0006, baseCollisionShapeIndex=shape,
                    basePosition=[(x + random.uniform(-8, 8)) * self.S, 0, -(y + random.uniform(-8, 8)) * self.S],
                    physicsClientId=self.cid)
                pybullet.changeDynamics(bid, -1, restitution=random.uniform(0.25, 0.5), lateralFriction=0.7,
                                        angularDamping=0.05, physicsClientId=self.cid)
                pybullet.resetBaseVelocity(bid, [math.cos(a) * sp * self.S, 0, -math.sin(a) * sp * self.S],
                                           [0, random.uniform(-14, 14), 0], physicsClientId=self.cid)
                self.bodies.append({"id": bid, "w": w, "h": h, "life": random.randint(300, 540),
                                    "col": random.choice(pal), "ang": 0.0, "x": x, "y": y})
            except Exception:
                break

    def step(self, platforms):
        if not self.ok:
            return
        try:
            self.sync_world(platforms)
            pybullet.stepSimulation(physicsClientId=self.cid)
            S = self.S
            for sh in self.bodies[:]:
                pos, orn = pybullet.getBasePositionAndOrientation(sh["id"], physicsClientId=self.cid)
                lin, ang = pybullet.getBaseVelocity(sh["id"], physicsClientId=self.cid)
                # lock to the play plane: no Y drift, spin only about Y
                th = 2.0 * math.atan2(orn[1], orn[3])
                pybullet.resetBasePositionAndOrientation(
                    sh["id"], [pos[0], 0, pos[2]], [0, math.sin(th / 2), 0, math.cos(th / 2)], physicsClientId=self.cid)
                pybullet.resetBaseVelocity(sh["id"], [lin[0], 0, lin[2]], [0, ang[1], 0], physicsClientId=self.cid)
                sh["x"], sh["y"], sh["ang"] = pos[0] / S, -pos[2] / S, th
                sh["life"] -= 1
                if sh["life"] <= 0 or sh["y"] > H + 300:
                    pybullet.removeBody(sh["id"], physicsClientId=self.cid)
                    self.bodies.remove(sh)
        except Exception as exc:
            print("PyBullet step failed, disabling:", exc)
            self.ok = False

    def draw(self, surf, ox):
        for sh in self.bodies:
            sx, sy = sh["x"] - ox, sh["y"]
            if not (-40 < sx < W + 40 and -40 < sy < H + 40):
                continue
            ca, sa = math.cos(sh["ang"]), math.sin(sh["ang"])
            hw, hh = sh["w"] / 2, sh["h"] / 2
            pts = [(sx + a * ca - b * sa, sy + a * sa + b * ca) for a, b in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh))]
            col = sh["col"]
            side = [(px + 3, py + 3) for px, py in pts]       # extruded depth
            pygame.draw.polygon(surf, tuple(int(c * 0.45) for c in col), side)
            pygame.draw.polygon(surf, col, pts)
            pygame.draw.line(surf, tuple(min(255, c + 60) for c in col), pts[0], pts[1], 2)
            pygame.draw.polygon(surf, (20, 22, 28), pts, 1)


