        pygame.draw.line(surf, hair_h, HP(-2, -11), HP(5, -9), 1)
        ey_ = HP(5.5, 0.5)
        if self.blink > 0:
            pygame.draw.line(surf, (30, 24, 34), (ey_[0] - 3, ey_[1]), (ey_[0] + 3, ey_[1]), 1)
        else:
            pygame.draw.ellipse(surf, (255, 255, 255), (ey_[0] - 3, ey_[1] - 3, 7, 6))
            pygame.draw.circle(surf, iris, (ey_[0] + f, ey_[1]), 2)
            pygame.draw.circle(surf, (20, 14, 26), (ey_[0] + f, ey_[1]), 1)
            pygame.draw.line(surf, (24, 18, 28), (ey_[0] - 3 * f, ey_[1] - 3), (ey_[0] + 4 * f, ey_[1] - 3), 1)
        pygame.draw.line(surf, (200, 110, 120), HP(6, 6.5), HP(8.5, 6.2), 1)       # mouth
        pygame.draw.line(surf, skin_d, HP(9.5, 1.5), HP(10.5, 3), 1)               # nose
        pygame.draw.circle(surf, (255, 170, 175), HP(4.5, 4), 2)                   # blush
        # side lock that frames the face
        pygame.draw.line(surf, hair_c, HP(2, -2), HP(1, 8), 3)
        if look:
            bz = [HP(-12, -2), HP(-10, -11), HP(-3, -16), HP(6, -15), HP(12, -9), HP(12, -5),
                  HP(5, -6.5), HP(-4, -5)]
            pygame.draw.polygon(surf, look["beret"], bz)
            pygame.draw.polygon(surf, (16, 28, 18), bz, 1)
            pygame.draw.line(surf, (12, 18, 12), HP(-8, -4.5), HP(11, -6), 2)
            pygame.draw.circle(surf, (225, 205, 120), HP(7, -9.5), 2)

        # rifle (held by both hands) - slung across the back during gesture emotes
        gox, goy, ca, sa, tx, ty, ff = self.gun_o
        if self.gun_hidden:
            a1 = P((sx - fwd[0] * 9 + ux * 9, sy - fwd[1] * 9 + uy * 9))
            a2 = P((hx - fwd[0] * 7 - ux * 4, hy - fwd[1] * 7 - uy * 4 + 6))
            _capsule(surf, (22, 22, 26), a1, a2, 4)
            pygame.draw.line(surf, (92, 92, 104), a1, (a1[0] + int(f * 5), a1[1] - 5), 2)
            draw_arm(self.sh_r, self.arm_r)
            draw_arm(self.sh_f, self.arm_f)
            return
        T = self.T
        def poly(col, pts, edge=None):
            pp = [P(T(l, h)) for l, h in pts]
            pygame.draw.polygon(surf, col, pp)
            if edge:
                pygame.draw.polygon(surf, edge, pp, 1)
        dark, mid, hi = (22, 22, 26), (46, 46, 54), (92, 92, 104)
        poly(dark, [(0, -1), (18, 1), (18, -4), (2, -9)], hi)                   # stock
        poly(dark, [(18, -5), (44, -5), (44, 3), (18, 3)], hi)                  # receiver
        poly(mid, [(20, 3), (42, 3), (40, 5), (22, 5)])                         # dust cover
        poly(dark, [(44, -4), (60, -4), (60, 1.5), (44, 1.5)], hi)              # handguard
        poly(mid, [(44, 3), (62, 3), (62, 4.4), (44, 4.4)])                     # gas tube
        _capsule(surf, (15, 15, 18), P(T(60, 0)), P(T(80, 0)), 3)               # barrel
        poly(dark, [(76, 0), (80, 0), (80, 4), (77, 4)])                        # front sight
        poly(dark, [(20, -5), (26, -5), (24, -13), (19, -12)], hi)              # pistol grip
        poly(dark, [(30, -5), (38, -5), (42, -17), (45, -23), (38, -24), (32, -14)], hi)  # curved mag
        # arms over the gun
        draw_arm(self.sh_r, self.arm_r)
        draw_arm(self.sh_f, self.arm_f)
        # muzzle flash
        if g is not None and g.get("mg_flash", 0) > 0:
            mx, my = P(self.muzzle)
            dx, dy = ca, sa
            pygame.draw.line(surf, (255, 238, 145), (mx, my), (int(mx + dx * 30), int(my + dy * 30)), 3)
            pygame.draw.polygon(surf, (255, 250, 205), [(mx, my),
                                (int(mx + dx * 20 - dy * 8), int(my + dy * 20 + dx * 8)),
                                (int(mx + dx * 13), int(my + dy * 13)),
                                (int(mx + dx * 20 + dy * 8), int(my + dy * 20 - dx * 8))])
            pygame.draw.circle(surf, (255, 255, 235), (int(mx + dx * 2), int(my + dy * 2)), 4)


