        pygame.draw.rect(screen, my_col, (W//2 - 280, 220, 240, 160), 3, border_radius=12)
        self.text(F_MID, "YOUR TEAM", W//2 - 160, 250, my_col, True)
        self.text(F_BIG, str(self.my_team), W//2 - 160, 310, (255, 255, 255), True)
        self.text(F_XS, "(you + %d allies)" % max(0, self.my_team-1), W//2 - 160, 360, (180, 180, 200), True)

        # Enemy box
        en_col = (255, 100, 100) if self.team_select == 1 else (100, 100, 120)
