def load_blackop_sprites():
    """Decode the embedded Black Op frames (called once at start-up, before build_art)."""
    import base64
    import io
    BLACKOP_BASE.clear()
    BLACKOP_LOOK.clear()
    for name, parts in BLACKOP_B64.items():
        raw = base64.b64decode("".join(parts))
        BLACKOP_BASE[name] = pygame.image.load(io.BytesIO(raw), name + ".png").convert_alpha()


def _blackop_recolor(surf, main, highlight):
    """Palette-swap the olive/tan camo of the reference art into one appearance's colours.
    Outline, NVG lenses, metal, skin and boots keep their colour; every camo pixel keeps its
    light and shade by mapping its brightness onto a dark -> main -> highlight ramp."""
    out = surf.copy()
    w, h = out.get_size()
    dark = [c * 0.22 for c in main]
    for y in range(h):
        for x in range(w):
            r, g, b, a = out.get_at((x, y))
            if a == 0:
                continue
            if max(r, g, b) - min(r, g, b) > 14 and r >= b and g >= b - 4:
                lum = (r + g + b) / 3.0
                if lum < 210:
                    t = max(0.0, min(1.0, (lum - 40.0) / 130.0))
                    if t < 0.5:
                        k = t * 2.0
                        c = [dark[i] + (main[i] - dark[i]) * k for i in range(3)]
                    else:
                        k = (t - 0.5) * 2.0
                        c = [main[i] + (highlight[i] - main[i]) * k for i in range(3)]
                    # deepen: boost saturation and darken so the body stands out from the scenery
                    gry = (c[0] + c[1] + c[2]) / 3.0
                    c = [max(0.0, min(255.0, (gry + (v - gry) * 1.5) * 0.82)) for v in c]
                    out.set_at((x, y), (int(c[0]), int(c[1]), int(c[2]), a))
    return out


def blackop_look(ai):
    """Scaled, recoloured frames for one player appearance (index into APPEARANCES)."""
    if ai in BLACKOP_LOOK:
        return BLACKOP_LOOK[ai]
    _, main, highlight, _ = APPEARANCES[ai]
    frames = {}
    for name, surf in BLACKOP_BASE.items():
        s = _blackop_recolor(surf, main, highlight)
        w, h = s.get_size()
        s = pygame.transform.smoothscale(s, (max(1, int(w * BLACKOP_SCALE)), max(1, int(h * BLACKOP_SCALE))))
        frames[name] = s
        frames[name + "_f"] = pygame.transform.flip(s, True, False)
    BLACKOP_LOOK[ai] = frames
    return frames


def blackop_preview(ai):
    """Still 'right' frame used by the appearance menu, fitted into the SPR box."""
    _, main, highlight, _ = APPEARANCES[ai]
    s = _blackop_recolor(BLACKOP_BASE["right"], main, highlight)
    w, h = s.get_size()
    k = min(SPR_W / float(w), SPR_H / float(h))
    return pygame.transform.smoothscale(s, (max(1, int(w * k)), max(1, int(h * k))))


