def gf_photo_frame(name, face):
    """Scaled girlfriend frame (facing right by default; flipped for face < 0)."""
    if not GF_PHOTO_BASE:
        import base64
        import io
        for n, parts in GF_PHOTO_B64.items():
            raw = base64.b64decode("".join(parts))
            GF_PHOTO_BASE[n] = pygame.image.load(io.BytesIO(raw), n + ".png").convert_alpha()
    key = (name, face >= 0)
    if key not in GF_PHOTO_SCALED:
        s = GF_PHOTO_BASE[name]
        w, h = s.get_size()
        k = GF_PHOTO_H / float(h)
        s = pygame.transform.smoothscale(s, (max(1, int(w * k)), GF_PHOTO_H))
        GF_PHOTO_SCALED[(name, True)] = s
        GF_PHOTO_SCALED[(name, False)] = pygame.transform.flip(s, True, False)
    return GF_PHOTO_SCALED[key]


def _elite_to_blue(surf):
    """Friendly-team variant: red goggles / scarf / patch trim become blue."""
    surf = surf.copy()
    w, h = surf.get_size()
    for y in range(h):
        for x in range(w):
            r, g, b, a = surf.get_at((x, y))
            if a and r > 70 and r > g * 2.2 + 10 and r > b * 2.2 + 10:
                surf.set_at((x, y), (b, int(g * 0.6 + r * 0.25), r, a))
    return surf


def load_elite_bot_sprites():
    """Decode the embedded sprite sheet frames for both teams (called once at start-up)."""
    import base64
    import io
    ELITE_BOT.clear()
    base = {}
    for name, parts in ELITE_BOT_B64.items():
        raw = base64.b64decode(parts if isinstance(parts, str) else "".join(parts))
        base[name] = pygame.image.load(io.BytesIO(raw), name + ".png").convert_alpha()
    for team in ("red", "blue"):
        frames = {}
        for name, surf in base.items():
            if team == "blue":
                surf = _elite_to_blue(surf)
            w, h = surf.get_size()
            s = pygame.transform.smoothscale(
                surf, (max(1, int(w * ELITE_BOT_SCALE)), max(1, int(h * ELITE_BOT_SCALE))))
            frames[name] = s
            frames[name + "_f"] = pygame.transform.flip(s, True, False)
        ELITE_BOT[team] = frames


def elite_bot_frame(team, name, face, look=None):
    """Return (surface, anchor_x_px, muzzle_x_px, muzzle_y_px) for a pose and facing.
    `look` selects the Black Op frames (player); otherwise the team's Military Bot frames."""
    if look is not None:
        frames, meta = look, BLACKOP_META
    else:
        frames, meta = (ELITE_BOT.get(team) or ELITE_BOT["red"]), ELITE_BOT_META
    if name in ("left", "right"):
        name = "right" if face > 0 else "left"
        surf = frames[name]
        ax, tx, ty = meta[name]
    else:
        ax, tx, ty = meta[name]
        if face > 0:
            surf = frames[name]
        else:
            surf = frames[name + "_f"]
            ax, tx = 1.0 - ax, 1.0 - tx
    w, h = surf.get_size()
    return surf, ax * w, tx * w, ty * h




# ---------------------------- MOBILE TOUCH LAYER ----------------------------
# Landscape touch controls. The original keyboard/mouse controls remain intact.
MOBILE_HOLD = set()
MOBILE_ENABLED = True
MOBILE_BUTTONS = [
    ("LEFT", pygame.Rect(24, 566, 76, 76), "hold_left"),
    ("RIGHT", pygame.Rect(108, 566, 76, 76), "hold_right"),
    ("JUMP", pygame.Rect(198, 566, 76, 76), "hold_jump"),
    ("FIRE", pygame.Rect(1080, 540, 86, 86), "hold_fire"),
    ("AIM", pygame.Rect(988, 590, 70, 54), "aim"),
    ("LOADOUT", pygame.Rect(930, 510, 88, 42), "key_b"),
    ("MISSIONS", pygame.Rect(1024, 486, 92, 42), "key_m"),
    ("GRENADE", pygame.Rect(1120, 486, 92, 42), "key_g"),
    ("SWAP", pygame.Rect(930, 462, 88, 42), "key_q"),
    ("MELEE", pygame.Rect(1024, 438, 92, 42), "key_f"),
    ("PAUSE", pygame.Rect(1120, 438, 92, 42), "key_escape"),
]
MOBILE_HIT_RECTS = {name: rect for name, rect, _ in MOBILE_BUTTONS}

class _MobileKeys:
    """Read-only pygame key-state adapter with touch buttons layered on top."""
    def __init__(self, base): self.base = base
    def __getitem__(self, key):
        if key in (pygame.K_a, pygame.K_LEFT) and "hold_left" in MOBILE_HOLD: return True
        if key in (pygame.K_d, pygame.K_RIGHT) and "hold_right" in MOBILE_HOLD: return True
        if key in (pygame.K_w, pygame.K_UP, pygame.K_SPACE) and "hold_jump" in MOBILE_HOLD: return True
        if key in (pygame.K_LSHIFT, pygame.K_RSHIFT) and "hold_sprint" in MOBILE_HOLD: return True
        return self.base[key]

def _mobile_event(game, action):
    keymap = {"key_b": pygame.K_b, "key_m": pygame.K_m, "key_g": pygame.K_g,
              "key_q": pygame.K_q, "key_f": pygame.K_f, "key_escape": pygame.K_ESCAPE,
              "key_l": pygame.K_l, "key_e": pygame.K_e, "key_t": pygame.K_t,
              "key_i": pygame.K_i, "key_o": pygame.K_o, "key_y": pygame.K_y,
              "key_h": pygame.K_h, "key_u": pygame.K_u, "key_c": pygame.K_c}
    if action in keymap:
        game.handle_event(pygame.event.Event(pygame.KEYDOWN, key=keymap[action], mod=0, unicode=""))

def draw_mobile_controls(game):
    if not MOBILE_ENABLED or game.state != "play": return
    overlay = pygame.Surface((W, H), pygame.SRCALPHA)
    for label, rect, action in MOBILE_BUTTONS:
        active = action in MOBILE_HOLD
        fill = (30, 150, 190, 205) if active else (10, 22, 38, 175)
        pygame.draw.rect(overlay, fill, rect, border_radius=14)
        pygame.draw.rect(overlay, (150, 220, 245, 230), rect, 2, border_radius=14)
        font = F_XS if len(label) > 5 else F_SM
        txt = font.render(label, True, (255, 255, 255))
        overlay.blit(txt, txt.get_rect(center=rect.center))
    # Light directional hint, plus a compact label for touch users.
    pygame.draw.rect(overlay, (5, 12, 24, 155), (20, 526, 260, 30), border_radius=8)
    overlay.blit(F_XS.render("MOVE  •  JUMP / JETPACK", True, (220, 240, 250)), (30, 534))
    screen.blit(overlay, (0, 0))

async def main():
    global BULLET, RL_BACKDROP
    load_blackop_sprites()
    build_art()
    load_elite_bot_sprites()
    BULLET = BulletDebris()
    RL_BACKDROP = RaylibBackdrop()
    game = Game()
    pygame.mouse.set_visible(True)
    while True:
        for ev in pygame.event.get():
            # Convert Android/iOS finger coordinates into the same logical coordinates
            # used by the existing menus. Pygame's normalized finger positions scale to W/H.
            if ev.type in (pygame.FINGERDOWN, pygame.FINGERMOTION, pygame.FINGERUP):
                pos = (max(0, min(W-1, int(ev.x * W))), max(0, min(H-1, int(ev.y * H))))
                if ev.type == pygame.FINGERDOWN:
                    handled = False
                    if game.state == "play":
                        for label, rect, action in MOBILE_BUTTONS:
                            if rect.collidepoint(pos):
                                if action.startswith("hold_"):
                                    MOBILE_HOLD.add(action)
                                else:
                                    _mobile_event(game, action)
                                handled = True
                                break
                    if not handled:
                        pygame.event.post(pygame.event.Event(pygame.MOUSEBUTTONDOWN, pos=pos, button=1))
                elif ev.type == pygame.FINGERMOTION:
                    pygame.mouse.set_pos(pos)
                else:
                    for label, rect, action in MOBILE_BUTTONS:
                        if action.startswith("hold_"):
                            MOBILE_HOLD.discard(action)
                    pygame.event.post(pygame.event.Event(pygame.MOUSEBUTTONUP, pos=pos, button=1))
                continue
            if ev.type == pygame.QUIT:
                if RL_BACKDROP:
                    RL_BACKDROP.close()
                pygame.quit()
                if not WEB:
                    sys.exit()
                return
            if ev.type == pygame.KEYDOWN and ev.key == pygame.K_F8 and game.state == "play":
                game.uniform_open = not game.uniform_open
                game.uniform_sel = game.uniform_idx
                game.loadout_open = game.team_menu = game.mission_menu = game.appearance_open = game.gf_dress_open = False
                if game.uniform_open and not game.aot_on(game.p):
                    game.banner = "Wardrobe is for the Survey Corps Scout - press L and pick it to see uniforms"
                    game.banner_t = 150
                continue
            if game.uniform_open:
                if ev.type == pygame.KEYDOWN:
                    n = len(SCOUT_UNIFORMS)
                    if ev.key == pygame.K_ESCAPE:
                        game.uniform_open = False
                    elif ev.key in (pygame.K_LEFT, pygame.K_a):
                        game.uniform_sel = (game.uniform_sel - 1) % n
                    elif ev.key in (pygame.K_RIGHT, pygame.K_d):
                        game.uniform_sel = (game.uniform_sel + 1) % n
                    elif ev.key in (pygame.K_UP, pygame.K_w):
                        game.uniform_sel = (game.uniform_sel - 10) % n
                    elif ev.key in (pygame.K_DOWN, pygame.K_s):
                        game.uniform_sel = (game.uniform_sel + 10) % n
                    elif ev.key in (pygame.K_RETURN, pygame.K_SPACE, pygame.K_KP_ENTER):
                        game.set_uniform(game.uniform_sel)
                        game.uniform_open = False
                elif ev.type == pygame.MOUSEBUTTONDOWN and ev.button == 1:
                    for i in range(len(SCOUT_UNIFORMS)):
                        if uniform_rect(i).collidepoint(ev.pos):
                            game.set_uniform(i)
                            game.uniform_open = False
                            break
                continue
            # K = instant Yor Forger transform for girlfriend
            if ev.type == pygame.KEYDOWN and ev.key == pygame.K_k and game.state == "play":
                if not game.girlfriend_guard:
                    game.toggle_girlfriend_guard()
                game.gf_yor = not game.gf_yor
                if game.gf_yor:
                    game.banner = "YOR FORGER TRANSFORM — F9 for 50 royal & spicy dresses"
                    game.banner_t = 180
                    play("unlock")
                else:
                    game.gf_dress_open = False
                    game.banner = "GIRLFRIEND LOOK RESTORED"
                    game.banner_t = 120
                    play("pickup")
                continue
            # F9 = Yor dress wardrobe (unlocked after K transform)
            if ev.type == pygame.KEYDOWN and ev.key == pygame.K_F9 and game.state == "play":
                if not game.gf_yor:
                    game.banner = "Press K first to transform girlfriend into Yor Forger"
                    game.banner_t = 150
                else:
                    game.gf_dress_open = not game.gf_dress_open
                    game.gf_dress_sel = game.gf_dress_idx
                    game.loadout_open = game.team_menu = game.mission_menu = game.appearance_open = game.uniform_open = False
                continue
            if game.gf_dress_open:
                if ev.type == pygame.KEYDOWN:
                    n = len(GF_DRESSES)
                    if ev.key == pygame.K_ESCAPE:
                        game.gf_dress_open = False
                    elif ev.key in (pygame.K_LEFT, pygame.K_a):
                        game.gf_dress_sel = (game.gf_dress_sel - 1) % n
                    elif ev.key in (pygame.K_RIGHT, pygame.K_d):
                        game.gf_dress_sel = (game.gf_dress_sel + 1) % n
                    elif ev.key in (pygame.K_UP, pygame.K_w):
                        game.gf_dress_sel = (game.gf_dress_sel - 10) % n
                    elif ev.key in (pygame.K_DOWN, pygame.K_s):
                        game.gf_dress_sel = (game.gf_dress_sel + 10) % n
                    elif ev.key in (pygame.K_RETURN, pygame.K_SPACE, pygame.K_KP_ENTER):
                        game.set_gf_dress(game.gf_dress_sel)
                        game.gf_dress_open = False
                elif ev.type == pygame.MOUSEBUTTONDOWN and ev.button == 1:
                    for i in range(len(GF_DRESSES)):
                        if gf_dress_rect(i).collidepoint(ev.pos):
                            game.set_gf_dress(i)
                            game.gf_dress_open = False
                            break
                continue
            if ev.type == pygame.KEYDOWN and ev.key in (pygame.K_F5, pygame.K_F6, pygame.K_F7, pygame.K_F10):
                k = {pygame.K_F5: "post", pygame.K_F6: "backdrop", pygame.K_F7: "shards", pygame.K_F10: "photo"}[ev.key]
                FX[k] = not FX[k]
                game.banner = "%s: %s" % (k.upper(), "ON" if FX[k] else "OFF")
                game.banner_t = 90
                continue
            game.handle_event(ev)
        pygame.mouse.set_visible(game.state != "play" or game.loadout_open or game.appearance_open or game.team_menu or game.mission_menu or game.environment_menu or game.emote_menu or game.uniform_open or game.gf_dress_open or game.rom_menu)
        game.update()
        game.update_special_ability()
        game.draw()
        draw_mobile_controls(game)
        if game.state == "play":
            game.draw_special_ability_fx()
        present_frame(game)
        # Pyglet's high-resolution clock advances the visual animation timeline
        # when installed; pygame clock remains the compatibility frame limiter.
        if PYGLET_AVAILABLE:
            pyglet.clock.tick()
        clock.tick(FPS)
        await asyncio.sleep(0)   # REQUIRED by pygbag: hands control back to the browser each frame

asyncio.run(main())
